function renderReview() {
  reviewContainer.innerHTML = '';
  const tpl = document.getElementById('reviewFileTpl');
  const rowTpl = document.getElementById('rowTpl');

  for (const f of files) {
    const clone = tpl.content.cloneNode(true);
    const el = clone.firstElementChild;
    el.querySelector('.rf-name').textContent = f.name;
    const inc = f.entries.filter(e => e.type === 'income').reduce((s, e) => s + e.amount, 0);
    const exp = f.entries.filter(e => e.type === 'expense').reduce((s, e) => s + e.amount, 0);
    el.querySelector('.rf-summary').textContent = `Income ${fmtMoney(inc)} · Expense ${fmtMoney(exp)} · Net ${fmtMoney(inc - exp)}`;
    const tbody = el.querySelector('tbody');

    f.entries.forEach((e, i) => {
      const row = rowTpl.content.cloneNode(true).firstElementChild;
      row.querySelector('.row-num').textContent = i + 1;
      const inDate = row.querySelector('.in-date');
      const inType = row.querySelector('.in-type');
      const inDesc = row.querySelector('.in-desc');
      const inAmt = row.querySelector('.in-amt');

      inDate.value = e.date;
      inType.value = e.type;
      inDesc.value = e.description;
      inAmt.value = e.amount;

      // Bind back to state
      const bind = (inp, key) => inp.addEventListener('change', () => {
        e[key] = inp.type === 'number' ? (parseFloat(inp.value) || 0) : inp.value;
        if (key === 'type') updateFileSummary(el, f);
      });
      bind(inDate, 'date');
      bind(inType, 'type');
      bind(inDesc, 'description');
      bind(inAmt, 'amount');

      row.querySelector('.btn-del-row').addEventListener('click', () => {
        row.remove();
        f.entries.splice(i, 1);
        updateFileSummary(el, f);
      });

      tbody.appendChild(row);
    });

    // Add row button for this file
    const addBtn = document.createElement('button');
    addBtn.type = 'button';
    addBtn.className = 'btn-outline';
    addBtn.textContent = 'Add row';
    addBtn.style.marginTop = '8px';
    addBtn.style.fontSize = '0.8rem';
    addBtn.addEventListener('click', () => {
      const newE = { date: f.entries.length ? f.entries[f.entries.length - 1].date : `${currentYear}-${String(f.month).padStart(2,'0')}-${String(f.day).padStart(2,'0')}`,
                     type: 'expense', description: '', amount: 0 };
      f.entries.push(newE);
      renderReview();
    });
    el.querySelector('.rf-table').after(addBtn);

    reviewContainer.appendChild(el);
  }
}

function updateFileSummary(el, f) {
  const inc = f.entries.filter(e => e.type === 'income').reduce((s, e) => s + e.amount, 0);
  const exp = f.entries.filter(e => e.type === 'expense').reduce((s, e) => s + e.amount, 0);
  el.querySelector('.rf-summary').textContent = `Income ${fmtMoney(inc)} · Expense ${fmtMoney(exp)} · Net ${fmtMoney(inc - exp)}`;
}

btnReprocess.addEventListener('click', processAll);
btnAddRow.addEventListener('click', () => {
  if (!files.length) return;
  const f = files[files.length - 1];
  const newE = { date: `${currentYear}-${String(f.month).padStart(2,'0')}-${String(f.day).padStart(2,'0')}`,
                 type: 'expense', description: '', amount: 0 };
  f.entries.push(newE);
  renderReview();
});

// ---------------------------------------------------------------------------
// Generate weekly invoices
// ---------------------------------------------------------------------------
function buildWeeks() {
  // Group all entries by (month, week)
  const weeks = new Map(); // weekNum -> {entries[], totalIncome, totalExpense}
  for (const f of files) {
    for (const e of f.entries) {
      const d = new Date(e.date);
      if (isNaN(d)) continue;
      const wk = weekOfMonth(d.getDate());
      if (!weeks.has(wk)) weeks.set(wk, { week: wk, entries: [], income: 0, expense: 0 });
      const w = weeks.get(wk);
      w.entries.push({ ...e, source: f.name });
      if (e.type === 'income') w.income += e.amount;
      else w.expense += e.amount;
    }
  }
  return Array.from(weeks.values()).sort((a, b) => a.week - b.week);
}

btnGenerate.addEventListener('click', () => {
  const weeks = buildWeeks();
  if (!weeks.length) {
    showToast('No entries to invoice. Add some rows first.');
    return;
  }
  renderWeekSelector(weeks);
  showWeek(weeks[0].week);
  showStep(stepInvoices);
});

function renderWeekSelector(weeks) {
  weekSelector.innerHTML = '';
  for (const w of weeks) {
    const chip = document.createElement('button');
    chip.type = 'button';
    chip.className = 'week-chip' + (w.week === weeks[0].week ? ' active' : '');
    chip.textContent = weekLabel(w.week);
    chip.addEventListener('click', () => showWeek(w.week));
    weekSelector.appendChild(chip);
  }
  // store weeks globally for showWeek
  window.__weeks = weeks;
}

let currentWeekNum = null;
function showWeek(weekNum) {
  currentWeekNum = weekNum;
  const weeks = window.__weeks;
  const w = weeks.find(x => x.week === weekNum);
  if (!w) return;

  // Update chip active state
  Array.from(weekSelector.children).forEach(c => {
    c.classList.toggle('active', c.textContent === weekLabel(weekNum));
  });

  const net = w.income - w.expense;
  const rowsHtml = w.entries.map((e, i) => {
    const cls = e.type === 'income' ? 'income' : 'expense';
    const sign = e.type === 'income' ? '+' : '−';
    return `
      <tr>
        <td>${i + 1}</td>
        <td>${escapeHtml(e.source)}</td>
        <td>${escapeHtml(e.description)}</td>
        <td class="${cls}">${e.type === 'income' ? 'Income' : 'Expense'}</td>
        <td class="amt">${sign} ${fmtMoney(e.amount)}</td>
      </tr>
    `;
  }).join('');

  invoicePreview.innerHTML = `
    <div class="invoice-card" id="invoice-${weekNum}">
      <div class="invoice-head">
        <div class="invoice-brand">Gamefy</div>
        <div class="invoice-meta">
          <div><strong>Invoice:</strong> INV-${String(currentYear).slice(2)}-${String(w.month || currentMonth()).padStart(2,'0')}-W${weekNum}</div>
          <div><strong>Week:</strong> Week ${weekNum} of ${monthName(w.month || currentMonth())} ${currentYear}</div>
          <div><strong>Days:</strong> ${(weekNum - 1) * 7 + 1} – ${Math.min(weekNum * 7, 31)}</div>
          <div><strong>Date:</strong> ${new Date().toLocaleDateString()}</div>
        </div>
      </div>
      <div class="invoice-title">Weekly Income / Expense Summary</div>
      <table class="inv-table">
        <thead>
          <tr>
            <th style="width:34px">#</th>
            <th style="width:180px">Source file</th>
            <th>Description</th>
            <th style="width:110px">Type</th>
            <th class="amt" style="width:120px">Amount</th>
          </tr>
        </thead>
        <tbody>${rowsHtml || '<tr><td colspan="5" style="text-align:center;color:#94a3b8">No entries</td></tr>'}</tbody>
      </table>
      <div class="invoice-totals">
        <div>Total Income: <span class="income">+ ${fmtMoney(w.income)}</span></div>
        <div>Total Expense: <span class="expense">− ${fmtMoney(w.expense)}</span></div>
        <div class="total-row">Net: ${net >= 0 ? '+' : ''} ${fmtMoney(net)}</div>
      </div>
      <div class="invoice-foot">Generated by Gamefy Invoice Builder · ${currentYear}</div>
    </div>
    <div style="display:flex; gap:8px; justify-content:flex-end; margin-top:10px;">
      <button type="button" class="btn-download-week" onclick="downloadWeekInvoice(${weekNum})">⬇ Download this week PDF</button>
    </div>
  `;
}

function currentMonth() {
  return files.length ? files[0].month : new Date().getMonth() + 1;
}
function monthName(m) {
  return new Date(currentYear, m - 1, 1).toLocaleString(undefined, { month: 'long' });
}

// Expose for inline onclick
window.downloadWeekInvoice = function(weekNum) {
  const weeks = window.__weeks;
  const w = weeks.find(x => x.week === weekNum);
  const doc = new jsPDF();
  const month = w.month || currentMonth();

  doc.setFontSize(20);
  doc.setFont('helvetica', 'bold');
  doc.text('GAMEFY', 20, 20);
  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');
  doc.text(`Invoice INV-${String(currentYear).slice(2)}-${String(month).padStart(2,'0')}-W${weekNum}`, 20, 32);
  doc.text(`Week ${weekNum} of ${monthName(month)} ${currentYear}`, 20, 40);
  doc.text(`Days ${(weekNum - 1) * 7 + 1} – ${Math.min(weekNum * 7, 31)}`, 20, 48);
  doc.text(`Date: ${new Date().toLocaleDateString()}`, 120, 32, { align: 'right' });

  const head = [['#', 'Source', 'Description', 'Type', 'Amount']];
  const body = w.entries.map((e, i) => [
    String(i + 1),
    e.source,
    e.description,
    e.type.charAt(0).toUpperCase() + e.type.slice(1),
    (e.type === 'income' ? '+ ' : '− ') + fmtMoney(e.amount),
  ]);
  body.push(['', '', 'Total Income', '', '+ ' + fmtMoney(w.income)]);
  body.push(['', '', 'Total Expense', '', '− ' + fmtMoney(w.expense)]);
  body.push(['', '', 'Net', '', (w.income - w.expense >= 0 ? '+ ' : '− ') + fmtMoney(Math.abs(w.income - w.expense))]);

  doc.autoTable({
    head,
    body,
    startY: 60,
    styles: { fontSize: 9 },
    headStyles: { fillColor: [37, 99, 235] },
    alternateRowStyles: { fillColor: [244, 246, 248] },
    columnStyles: { 0: { cellWidth: 10 }, 3: { cellWidth: 25 }, 4: { cellWidth: 30, halign: 'right' } },
  });

  const finalY = doc.lastAutoTable.finalY + 10;
  doc.setFontSize(11);
  doc.setFont('helvetica', 'bold');
  doc.text(`Net: ${w.income - w.expense >= 0 ? '+' : '−'} ${fmtMoney(Math.abs(w.income - w.expense))}`, 20, finalY);

  doc.save(`Gamefy_Invoice_Week${weekNum}_${monthName(month)}${currentYear}.pdf`);
};

// ---------------------------------------------------------------------------
// Download all as ZIP
// ---------------------------------------------------------------------------
btnDownloadAll.addEventListener('click', async () => {
  const weeks = buildWeeks();
  if (!weeks.length) {
    showToast('No invoices to download.');
    return;
  }
  const btn = btnDownloadAll;
  const orig = btn.textContent;
  btn.disabled = true;
  btn.textContent = 'Preparing ZIP...';
  try {
    const JSZip = window.JSZip;
    if (!JSZip) {
      // Load JSZip dynamically
      await loadScript('https://unpkg.com/jszip@3.10.1/dist/jszip.min.js');
    }
    const zip = new window.JSZip();
    for (const w of weeks) {
      const doc = new jsPDF();
      const month = w.month || currentMonth();
      doc.setFontSize(20);
      doc.setFont('helvetica', 'bold');
      doc.text('GAMEFY', 20, 20);
      doc.setFontSize(10);
      doc.setFont('helvetica', 'normal');
      doc.text(`Invoice INV-${String(currentYear).slice(2)}-${String(month).padStart(2,'0')}-W${w.week}`, 20, 32);
      doc.text(`Week ${w.week} of ${monthName(month)} ${currentYear}`, 20, 40);
      doc.text(`Days ${(w.week - 1) * 7 + 1} – ${Math.min(w.week * 7, 31)}`, 20, 48);
      doc.text(`Date: ${new Date().toLocaleDateString()}`, 120, 32, { align: 'right' });

      const head = [['#', 'Source', 'Description', 'Type', 'Amount']];
      const body = w.entries.map((e, i) => [
        String(i + 1), e.source, e.description,
        e.type.charAt(0).toUpperCase() + e.type.slice(1),
        (e.type === 'income' ? '+ ' : '− ') + fmtMoney(e.amount),
      ]);
      body.push(['', '', 'Total Income', '', '+ ' + fmtMoney(w.income)]);
      body.push(['', '', 'Total Expense', '', '− ' + fmtMoney(w.expense)]);
      body.push(['', '', 'Net', '', (w.income - w.expense >= 0 ? '+ ' : '− ') + fmtMoney(Math.abs(w.income - w.expense))]);

      doc.autoTable({
        head, body, startY: 60,
        styles: { fontSize: 9 },
        headStyles: { fillColor: [37, 99, 235] },
        alternateRowStyles: { fillColor: [244, 246, 248] },
        columnStyles: { 0: { cellWidth: 10 }, 3: { cellWidth: 25 }, 4: { cellWidth: 30, halign: 'right' } },
      });

      const pdfBytes = doc.output('arraybuffer');
      zip.file(`Gamefy_Invoice_Week${w.week}_${monthName(month)}${currentYear}.pdf`, pdfBytes);
    }
    const blob = await zip.generateAsync({ type: 'blob' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `Gamefy_Invoices_Month${String(currentMonth()).padStart(2,'0')}_${currentYear}.zip`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  } catch (err) {
    console.error(err);
    showToast('Failed to create ZIP: ' + err.message);
  } finally {
    btn.disabled = false;
    btn.textContent = orig;
  }
});

function loadScript(src) {
  return new Promise((resolve, reject) => {
    const s = document.createElement('script');
    s.src = src;
    s.onload = resolve;
    s.onerror = reject;
    document.head.appendChild(s);
  });
}

btnBack.addEventListener('click', () => showStep(stepReview));

// ---------------------------------------------------------------------------
// Toast
// ---------------------------------------------------------------------------
function showToast(msg) {
  let toast = document.getElementById('toast');
  if (!toast) {
    toast = document.createElement('div');
    toast.id = 'toast';
    Object.assign(toast.style, {
      position: 'fixed', bottom: '20px', left: '50%', transform: 'translateX(-50%)',
      background: '#111827', color: '#fff', padding: '10px 16px', borderRadius: '6px',
      fontSize: '0.9rem', opacity: '0', transition: 'opacity 0.3s', pointerEvents: 'none',
      zIndex: 1000,
    });
    document.body.appendChild(toast);
  }
  toast.textContent = msg;
  toast.style.opacity = '1';
  setTimeout(() => { toast.style.opacity = '0'; }, 3000);
}

