.sheet-head { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 14px; border-bottom: 2px solid #111827; padding-bottom: 10px; }
.sheet-title { font-weight: 800; font-size: 1.25rem; color: #111827; text-transform: uppercase; letter-spacing: 1px; }
.sheet-meta { text-align: right; font-size: 0.85rem; color: #64748b; }
.sheet-meta div { margin: 2px 0; }
.inv-table { width: 100%; border-collapse: collapse; margin: 10px 0; font-size: 0.88rem; }
.inv-table th { text-align: left; border-bottom: 2px solid #111827; padding: 8px 6px; color: #334155; font-size: 0.8rem; }
.inv-table td { border-bottom: 1px solid #eef2f7; padding: 8px 6px; vertical-align: top; }
.inv-table .amt { text-align: right; font-variant-numeric: tabular-nums; }
.inv-table .src { font-size: 0.8rem; color: #64748b; max-width: 150px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.inv-table tfoot td { border-top: 2px solid #111827; font-weight: 700; padding-top: 10px; color: #111827; }
.inv-table tfoot .label { text-align: right; padding-right: 8px; }
.sheet-foot { margin-top: 14px; font-size: 0.78rem; color: #94a3b8; text-align: center; }

@media (max-width: 640px) {
  .wrap { padding: 16px 12px; }
  .card { padding: 20px 16px; }
  .toolbar { flex-direction: column; }
  .toolbar-right { justify-content: flex-start; }
  #dataGrid th, #dataGrid td { padding: 6px 4px; font-size: 0.8rem; }
}

/**
 * Gamefy Weekly Invoice Builder (Excel edition)
 * - Drop PDFs named day-month (e.g. 15-03.pdf)
 * - Extract income/expense table from each PDF
 * - Live editable data grid in the browser
 * - Export one .xlsx workbook with a sheet per week
 */

pdfjsLib.GlobalWorkerOptions.workerSrc =
  'https://unpkg.com/pdfjs-dist@4.8.69/build/pdf.worker.min.js';

// ---------------------------------------------------------------------------
// State
// ---------------------------------------------------------------------------
let files = []; // { file, name, day, month, year, entries: [], processed }
let currentYear = new Date().getFullYear();

// ---------------------------------------------------------------------------
// Elements
// ---------------------------------------------------------------------------
const dropZone = document.getElementById('dropZone');
const fileInput = document.getElementById('fileInput');
const browseBtn = document.getElementById('browseBtn');
const fileList = document.getElementById('fileList');

const stepDrop = document.getElementById('stepDrop');
const stepData = document.getElementById('stepData');
const stepExcel = document.getElementById('stepExcel');

const btnReprocess = document.getElementById('btnReprocess');
const btnAddRow = document.getElementById('btnAddRow');
const btnToExcel = document.getElementById('btnToExcel');
const btnBackData = document.getElementById('btnBackData');
const btnDownloadXlsx = document.getElementById('btnDownloadXlsx');

const gridTbody = document.querySelector('#dataGrid tbody');
const gridSummary = document.getElementById('gridSummary');
const weekTabs = document.getElementById('weekTabs');
const sheetPreviews = document.getElementById('sheetPreviews');

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------
function showStep(el) {
  [stepDrop, stepData, stepExcel].forEach(s => s.classList.remove('visible'));
  el.classList.add('visible');
}
function escapeHtml(t) {
  if (t == null) return '';
  return String(t).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
}
function fmtMoney(n) {
  const v = Number(n) || 0;
  return v.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}
function parseDayMonth(name) {
  const m = name.match(/^(\d{1,2})[-_](\d{1,2})/);
  if (!m) return null;
  return { day: parseInt(m[1],10), month: parseInt(m[2],10) };
}
function weekOfMonth(day) { return Math.ceil(day / 7); }
function weekLabel(w) {
  const start = (w-1)*7 + 1;
  let end = w*7;
  if (end > 31) end = 31;
  return `Week ${w} (days ${start}-${end})`;
}
function monthName(m) {
  return new Date(currentYear, m-1, 1).toLocaleString(undefined, { month: 'long' });
}
function showToast(msg) {
  let t = document.getElementById('toast');
  if (!t) {
    t = document.createElement('div');
    t.id = 'toast';
    Object.assign(t.style, {
      position:'fixed', bottom:'20px', left:'50%', transform:'translateX(-50%)',
      background:'#111827', color:'#fff', padding:'10px 16px', borderRadius:'6px',
      fontSize:'0.9rem', opacity:'0', transition:'opacity 0.3s', pointerEvents:'none', zIndex:1000
    });
    document.body.appendChild(t);
  }
  t.textContent = msg; t.style.opacity = '1';
  setTimeout(() => t.style.opacity = '0', 3000);
}

// ---------------------------------------------------------------------------
// Drag & drop
// ---------------------------------------------------------------------------
['dragenter','dragover'].forEach(evt => dropZone.addEventListener(evt, e => { e.preventDefault(); dropZone.classList.add('dragover'); }));
['dragleave','drop'].forEach(evt => dropZone.addEventListener(evt, e => { e.preventDefault(); dropZone.classList.remove('dragover'); }));
dropZone.addEventListener('drop', e => {
  const pdfs = Array.from(e.dataTransfer.files).filter(f => f.type === 'application/pdf' || f.name.toLowerCase().endsWith('.pdf'));
  addFiles(pdfs);
});
browseBtn.addEventListener('click', () => fileInput.click());
fileInput.addEventListener('change', e => { addFiles(Array.from(fileInput.files)); fileInput.value = ''; });

function addFiles(arr) {
  for (const f of arr) {
    const p = parseDayMonth(f.name);
    if (!p) { showToast(`Skipped "${f.name}": name must be like 15-03.pdf`); continue; }
    if (files.some(x => x.name === f.name && x.day === p.day && x.month === p.month)) continue;
    files.push({ file: f, name: f.name, day: p.day, month: p.month, year: currentYear, entries: [], processed: false });
  }
  renderFileList();
  if (files.length) showStep(stepDrop);
}

function renderFileList() {
  fileList.innerHTML = '';
  const tpl = document.getElementById('fileCardTpl');
  for (const f of files) {
    const clone = tpl.content.cloneNode(true);
    const card = clone.firstElementChild;
    card.querySelector('.file-name').textContent = f.name;
    card.querySelector('.meta-day').textContent = f.day;
    card.querySelector('.meta-month').textContent = f.month;
    card.querySelector('.meta-count').textContent = f.entries.length;
    const st = card.querySelector('.file-status');
    st.textContent = f.processed ? (f.entries.length ? `✓ ${f.entries.length} entries` : '⚠ No table found') : 'Pending';
    st.className = 'file-status ' + (f.processed && f.entries.length ? '' : f.processed ? 'warn' : '');
    card.querySelector('.btn-remove').addEventListener('click', () => {
      files = files.filter(x => x !== f);
      renderFileList();
      renderGrid();
    });
    fileList.appendChild(card);
  }
}

// ---------------------------------------------------------------------------
// PDF processing
// ---------------------------------------------------------------------------
async function processAll() {
  const b = btnReprocess; const orig = b.textContent;
  b.disabled = true; b.textContent = 'Processing...';
  try {
    for (const f of files) await processPdf(f);
    renderFileList();
    showStep(stepData);
    renderGrid();
  } finally { b.disabled = false; b.textContent = orig; }
}
async function processPdf(f) {
  const ab = await f.file.arrayBuffer();
  const pdf = await pdfjsLib.getDocument({ data: ab }).promise;
  const allText = [];
  for (let i = 1; i <= pdf.numPages; i++) {
    const page = await pdf.getPage(i);
    const content = await page.getTextContent();
    content.items.sort((a,b) => {
      const ay = a.transform[5]||0, by = b.transform[5]||0;
      if (Math.abs(ay-by) > 2) return by - ay;
      return (a.transform[4]||0) - (b.transform[4]||0);
    });
    allText.push(content.items.map(it => it.str).join(' '));
  }
  f.entries = parseTableText(allText.join('\n'), f.day, f.month, f.year);
  f.processed = true;
}
function parseTableText(text, day, month, year) {
  const lines = text.split(/\r?\n/).map(l => l.trim()).filter(l => l.length > 0);
  const entries = [];
  const moneyRegex = /(-?\d{1,3}(?:[,\.]\d{3})*(?:[.,]\d{2})?|-?\d+(?:[.,]\d{2}))/;
  const incomeK = /income|received|deposit|credit|payment received|salary|revenue/i;
  const expenseK = /expense|paid|purchase|debit|withdrawal|charge|fee|cost/i;
  for (const line of lines) {
    const mm = line.match(moneyRegex); if (!mm) continue;
    let cleaned = mm[0].replace(/[^0-9.,-]/g,'');
    const lastDot = cleaned.lastIndexOf('.'), lastComma = cleaned.lastIndexOf(',');
    const decSep = lastComma > lastDot ? ',' : '.';
    let intPart, decPart;
    if (decSep === ',') { const p = cleaned.split(','); decPart = p.pop(); intPart = p.join('').replace(/\./g,''); }
    else { const p = cleaned.split('.'); decPart = p.pop(); intPart = p.join('').replace(/,/g,''); }
    const num = parseFloat((intPart + '.' + decPart).replace(/[^0-9.-]/g,''));
    if (!isFinite(num)) continue;
    const amount = Math.abs(num);
    let desc = line.replace(moneyRegex,'').trim().replace(/[-–—:|]\s*$/,'').trim();
    if (!desc) desc = 'Entry';
    let type = 'expense';
    if (incomeK.test(desc)) type = 'income';
    else if (expenseK.test(desc)) type = 'expense';
    else if (num < 0) type = 'expense';
    entries.push({ date: `${String(year).padStart(4,'0')}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}`, type, description: desc, amount });
  }
  const seen = new Set();
  return entries.filter(e => { const k = `${e.date}|${e.type}|${e.description}|${e.amount}`; if (seen.has(k)) return false; seen.add(k); return true; });
}

// ---------------------------------------------------------------------------
// Live editable grid
// ---------------------------------------------------------------------------
function renderGrid() {
  gridTbody.innerHTML = '';
  let all = [];
  for (const f of files) all = all.concat(f.entries.map(e => ({ ...e, source: f.name, _file: f })));
  let totInc = 0, totExp = 0;
  all.forEach((e, i) => {
    if (e.type === 'income') totInc += e.amount; else totExp += e.amount;
    const tr = document.createElement('tr');
    tr.innerHTML = `
      <td><span class="row-num">${i+1}</span></td>
      <td><input type="date" class="c-date" value="${escapeHtml(e.date)}"></td>
      <td><select class="c-type"><option value="income">Income</option><option value="expense">Expense</option></select></td>
      <td><input type="text" class="c-desc" value="${escapeHtml(e.description)}"></td>
      <td><input type="number" class="c-amt" step="0.01" min="0" value="${e.amount}"></td>
      <td class="src">${escapeHtml(e.source)}</td>
      <td><button type="button" class="btn-del-row danger">×</button></td>
    `;
    const sel = tr.querySelector('.c-type'); sel.value = e.type;
    const bind = (inp, key) => inp.addEventListener('change', () => {
      e[key] = inp.type === 'number' ? (parseFloat(inp.value) || 0) : inp.value;
      if (key === 'type') sel.value = e.type;
      renderSummary();
    });
    bind(tr.querySelector('.c-date'), 'date');
    bind(sel, 'type');
    bind(tr.querySelector('.c-desc'), 'description');
    bind(tr.querySelector('.c-amt'), 'amount');
    tr.querySelector('.btn-del-row').addEventListener('click', () => {
      e._file.entries = e._file.entries.filter(x => x !== e);
      tr.remove();
      renderGrid(); // re-index
      renderSummary();
    });
    gridTbody.appendChild(tr);
  });
  renderSummary(all, totInc, totExp);
}
function renderSummary(all, totInc, totExp) {
  if (!all) { all = []; for (const f of files) all = all.concat(f.entries); totInc = totExp = 0; all.forEach(e => e.type === 'income' ? totInc += e.amount : totExp += e.amount); }
  gridSummary.innerHTML = `<b>Total Income:</b> <span class="income">+ ${fmtMoney(totInc)}</span> &nbsp;|&nbsp; <b>Total Expense:</b> <span class="expense">− ${fmtMoney(totExp)}</span> &nbsp;|&nbsp; <b>Net:</b> ${totInc - totExp >= 0 ? '+' : '−'} ${fmtMoney(Math.abs(totInc - totExp))} &nbsp;|&nbsp; <b>Rows:</b> ${all.length}`;
}
btnReprocess.addEventListener('click', processAll);
btnAddRow.addEventListener('click', () => {
  if (!files.length) { showToast('Add PDFs first'); return; }
  const f = files[files.length - 1];
  const d = `${currentYear}-${String(f.month).padStart(2,'0')}-${String(f.day).padStart(2,'0')}`;
  f.entries.push({ date: d, type: 'expense', description: '', amount: 0 });
  renderGrid();
});
btnToExcel.addEventListener('click', () => {
  const weeks = buildWeeks();
  if (!weeks.length) { showToast('No data to export'); return; }
  renderWeekTabs(weeks);
  showSheet(weeks[0].week);
  showStep(stepExcel);
});

// ---------------------------------------------------------------------------
// Weeks & sheets
// ---------------------------------------------------------------------------
function buildWeeks() {
  const map = new Map();
  for (const f of files) for (const e of f.entries) {
    const d = new Date(e.date); if (isNaN(d)) continue;
    const wk = weekOfMonth(d.getDate());
    if (!map.has(wk)) map.set(wk, { week: wk, month: d.getMonth()+1, entries: [], inc: 0, exp: 0 });
    const w = map.get(wk); w.entries.push({ ...e, source: f.name });
    if (e.type === 'income') w.inc += e.amount; else w.exp += e.amount;
  }
  return Array.from(map.values()).sort((a,b) => a.week - b.week);
}
function renderWeekTabs(weeks) {
  weekTabs.innerHTML = '';
  for (const w of weeks) {
    const tab = document.createElement('button');
    tab.type = 'button'; tab.className = 'week-tab' + (w.week === weeks[0].week ? ' active' : '');
    tab.textContent = weekLabel(w.week);
    tab.addEventListener('click', () => showSheet(w.week));
    weekTabs.appendChild(tab);
  }
  window.__weeks = weeks;
}
let curWeek = null;
function showSheet(weekNum) {
  curWeek = weekNum;
  const weeks = window.__weeks;
  const w = weeks.find(x => x.week === weekNum);
  if (!w) return;
  Array.from(weekTabs.children).forEach(c => c.classList.toggle('active', c.textContent === weekLabel(weekNum)));
  const net = w.inc - w.exp;
  const rows = w.entries.map((e, i) => `
    <tr>
      <td>${i+1}</td>
      <td class="src">${escapeHtml(e.source)}</td>
      <td>${escapeHtml(e.description)}</td>
      <td class="${e.type}">${e.type.charAt(0).toUpperCase() + e.type.slice(1)}</td>
      <td class="amt">${e.type === 'income' ? '+ ' : '− '}${fmtMoney(e.amount)}</td>
    </tr>
  `).join('');
  sheetPreviews.innerHTML = `
    <div class="sheet-card" id="sheet-${weekNum}">
      <div class="sheet-head">
        <div class="sheet-title">Week ${weekNum}</div>
        <div class="sheet-meta">
          <div><strong>Month:</strong> ${monthName(w.month || currentMonth())} ${currentYear}</div>
          <div><strong>Days:</strong> ${(weekNum-1)*7 + 1} – ${Math.min(weekNum*7, 31)}</div>
          <div><strong>Entries:</strong> ${w.entries.length}</div>
        </div>
      </div>
      <table class="inv-table">
        <thead><tr><th style="width:34px">#</th><th style="width:160px">Source file</th><th>Description</th><th style="width:110px">Type</th><th class="amt" style="width:130px">Amount</th></tr></thead>
        <tbody>${rows || '<tr><td colspan="5" style="text-align:center;color:#94a3b8">No entries</td></tr>'}</tbody>
        <tfoot>
          <tr><td class="label" colspan="4">Total Income</td><td class="amt">+ ${fmtMoney(w.inc)}</td></tr>
          <tr><td class="label" colspan="4">Total Expense</td><td class="amt">− ${fmtMoney(w.exp)}</td></tr>
          <tr><td class="label" colspan="4">Net</td><td class="amt">${net >= 0 ? '+ ' : '− '}${fmtMoney(Math.abs(net))}</td></tr>
        </tfoot>
      </table>
      <div class="sheet-foot">Sheet: Week ${weekNum} · Gamefy Invoice Builder · ${currentYear}</div>
    </div>
  `;
}
function currentMonth() { return files.length ? files[0].month : new Date().getMonth()+1; }

// ---------------------------------------------------------------------------
// Excel export (SheetJS) - one sheet per week
// ---------------------------------------------------------------------------
btnDownloadXlsx.addEventListener('click', () => {
  const weeks = buildWeeks();
  if (!weeks.length) { showToast('Nothing to export'); return; }
  const wb = XLSX.utils.book_new();
  for (const w of weeks) {
    const rows = [['#', 'Source file', 'Date', 'Description', 'Type', 'Amount']];
    w.entries.forEach((e, i) => rows.push([i+1, e.source, e.date, e.description, e.type.charAt(0).toUpperCase() + e.type.slice(1), e.type === 'income' ? +e.amount : -e.amount]));
    rows.push(['', '', '', 'Total Income', '', w.inc]);
    rows.push(['', '', '', 'Total Expense', '', -w.exp]);
    rows.push(['', '', '', 'Net', '', w.inc - w.exp]);
    const ws = XLSX.utils.aoa_to_sheet(rows);
    // column widths
    ws['!cols'] = [
      { width: 5 }, { width: 22 }, { width: 12 }, { width: 38 }, { width: 12 }, { width: 14 }
    ];
    XLSX.utils.book_append_sheet(wb, ws, `Week ${w.week}`);
  }
  const fname = `Gamefy_Invoices_Month${String(currentMonth()).padStart(2,'0')}_${currentYear}.xlsx`;
  XLSX.writeFile(wb, fname);
  showToast(`Downloaded ${fname}`);
});

btnBackData.addEventListener('click', () => showStep(stepData));

// init
renderFileList();

