122:     st.className = 'file-status ' + (f.processed && f.entries.length ? '' : f.processed ? 'warn' : '');
123:     card.querySelector('.btn-remove').addEventListener('click', () => {
124:       files = files.filter(x => x !== f);
125:       renderFileList();
126:       renderGrid();
127:     });
128:     fileList.appendChild(card);
129:   }
130: }
