132: // ---------------------------------------------------------------------------
133: // PDF processing
134: // ---------------------------------------------------------------------------
135: async function processAll() {
136:   const b = btnReprocess; const orig = b.textContent;
137:   b.disabled = true; b.textContent = 'Processing...';
138:   try {
139:     for (const f of files) await processPdf(f);
140:     renderFileList();
141:     showStep(stepData);
142:     renderGrid();
143:   } finally { b.disabled = false; b.textContent = orig; }
144: }
145: async function processPdf(f) {
146:   const ab = await f.file.arrayBuffer();
147:   const pdf = await pdfjsLib.getDocument({ data: ab }).promise;
148:   const allText = [];
149:   for (let i = 1; i <= pdf.numPages; i++) {
150:     const page = await pdf.getPage(i);
151:     const content = await page.getTextContent();
152:     content.items.sort((a,b) => {
153:       const ay = a.transform[5]||0, by = b.transform[5]||0;
154:       if (Math.abs(ay-by) > 2) return by - ay;
155:       return (a.transform[4]||0) - (b.transform[4]||0);
156:     });
157:     allText.push(content.items.map(it => it.str).join(' '));
158:   }
159:   f.entries = parseTableText(allText.join('\n'), f.day, f.month, f.year);
160:   f.processed = true;
161: }
162: function parseTableText(text, day, month, year) {
163:   const lines = text.split(/\r?\n/).map(l => l.trim()).filter(l => l.length > 0);
164:   const entries = [];
165:   const moneyRegex = /(-?\d{1,3}(?:[,\.]\d{3})*(?:[.,]\d{2})?|-?\d+(?:[.,]\d{2}))/;
166:   const incomeK = /income|received|deposit|credit|payment received|salary|revenue/i;
167:   const expenseK = /expense|paid|purchase|debit|withdrawal|charge|fee|cost/i;
168:   for (const line of lines) {
169:     const mm = line.match(moneyRegex); if (!mm) continue;
170:     let cleaned = mm[0].replace(/[^0-9.,-]/g,'');
171:     const lastDot = cleaned.lastIndexOf('.'), lastComma = cleaned.lastIndexOf(',');
172:     const decSep = lastComma > lastDot ? ',' : '.';
173:     let intPart, decPart;
174:     if (decSep === ',') { const p = cleaned.split(','); decPart = p.pop(); intPart = p.join('').replace(/\./g,''); }
175:     else { const p = cleaned.split('.'); decPart = p.pop(); intPart = p.join('').replace(/,/g,''); }
176:     const num = parseFloat((intPart + '.' + decPart).replace(/[^0-9.-]/g,''));
177:     if (!isFinite(num)) continue;
178:     const amount = Math.abs(num);
179:     let desc = line.replace(moneyRegex,'').trim().replace(/[-–—:|]\s*$/,'').trim();
180:     if (!desc) desc = 'Entry';
181:     let type = 'expense';
182:     if (incomeK.test(desc)) type = 'income';
183:     else if (expenseK.test(desc)) type = 'expense';
184:     else if (num < 0) type = 'expense';
185:     entries.push({ date: `${String(year).padStart(4,'0')}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}`, type, description: desc, amount });
186:   }
187:   const seen = new Set();
188:   return entries.filter(e => { const k = `${e.date}|${e.type}|${e.description}|${e.amount}`; if (seen.has(k)) return false; seen.add(k); return true; });
189: }
190: 
191: // ---------------------------------------------------------------------------
192: // Live editable grid
193: // ---------------------------------------------------------------------------
194: function renderGrid() {
195:   gridTbody.innerHTML = '';
196:   let all = [];
197:   for (const f of files) all = all.concat(f.entries.map(e => ({ ...e, source: f.name, _file: f })));
198:   let totInc = 0, totExp = 0;
199:   all.forEach((e, i) => {
200:     if (e.type === 'income') totInc += e.amount; else totExp += e.amount;
201:     const tr = document.createElement('tr');
202:     tr.innerHTML = `
203:       <td><span class="row-num">${i+1}</span></td>
204:       <td><input type="date" class="c-date" value="${escapeHtml(e.date)}"></td>
205:       <td><select class="c-type"><option value="income">Income</option><option value="expense">Expense</option></select></td>
206:       <td><input type="text" class="c-desc" value="${escapeHtml(e.description)}"></td>
207:       <td><input type="number" class="c-amt" step="0.01" min="0" value="${e.amount}"></td>
208:       <td class="src">${escapeHtml(e.source)}</td>
209:       <td><button type="button" class="btn-del-row danger">×</button></td>
210:     `;
211:     const sel = tr.querySelector('.c-type'); sel.value = e.type;
212:     const bind = (inp, key) => inp.addEventListener('change', () => {
213:       e[key] = inp.type === 'number' ? (parseFloat(inp.value) || 0) : inp.value;
214:       if (key === 'type') sel.value = e.type;
215:       renderSummary();
216:     });
217:     bind(tr.querySelector('.c-date'), 'date');
218:     bind(sel, 'type');
219:     bind(tr.querySelector('.c-desc'), 'description');
220:     bind(tr.querySelector('.c-amt'), 'amount');
221:     tr.querySelector('.btn-del-row').addEventListener('click', () => {
222:       e._file.entries = e._file.entries.filter(x => x !== e);
223:       tr.remove();
224:       renderGrid(); // re-index
225:       renderSummary();
226:     });
227:     gridTbody.appendChild(tr);
228:   });
229:   renderSummary(all, totInc, totExp);
230: }
231: function renderSummary(all, totInc, totExp) {
232:   if (!all) { all = []; for (const f of files) all = all.concat(f.entries); totInc = totExp = 0; all.forEach(e => e.type === 'income' ? totInc += e.amount : totExp += e.amount); }
233:   gridSummary.innerHTML = `<b>Total Income:</b> <span class="income">+ ${fmtMoney(totInc)}</span> &nbsp;|&nbsp; <b>Total Expense:</b> <span class="expense">− ${fmtMoney(totExp)}</span> &nbsp;|&nbsp; <b>Net:</b> ${totInc - totExp >= 0 ? '+' : '−'} ${fmtMoney(Math.abs(totInc - totExp))} &nbsp;|&nbsp; <b>Rows:</b> ${all.length}`;
234: }
235: btnReprocess.addEventListener('click', processAll);
236: btnAddRow.addEventListener('click', () => {
237:   if (!files.length) { showToast('Add PDFs first'); return; }
238:   const f = files[files.length - 1];
239:   const d = `${currentYear}-${String(f.month).padStart(2,'0')}-${String(f.day).padStart(2,'0')}`;
240:   f.entries.push({ date: d, type: 'expense', description: '', amount: 0 });
241:   renderGrid();
242: });
243: btnToExcel.addEventListener('click', () => {
244:   const weeks = buildWeeks();
245:   if (!weeks.length) { showToast('No data to export'); return; }
246:   renderWeekTabs(weeks);
247:   showSheet(weeks[0].week);
248:   showStep(stepExcel);
249: });
250: 
251: // ---------------------------------------------------------------------------
252: // Weeks & sheets
253: // ---------------------------------------------------------------------------
254: function buildWeeks() {
255:   const map = new Map();
256:   for (const f of files) for (const e of f.entries) {
257:     const d = new Date(e.date); if (isNaN(d)) continue;
258:     const wk = weekOfMonth(d.getDate());
259:     if (!map.has(wk)) map.set(wk, { week: wk, month: d.getMonth()+1, entries: [], inc: 0, exp: 0 });
260:     const w = map.get(wk); w.entries.push({ ...e, source: f.name });
261:     if (e.type === 'income') w.inc += e.amount; else w.exp += e.amount;
262:   }
263:   return Array.from(map.values()).sort((a,b) => a.week - b.week);
264: }
265: function renderWeekTabs(weeks) {
266:   weekTabs.innerHTML = '';
267:   for (const w of weeks) {
268:     const tab = document.createElement('button');
269:     tab.type = 'button'; tab.className = 'week-tab' + (w.week === weeks[0].week ? ' active' : '');
270:     tab.textContent = weekLabel(w.week);
271:     tab.addEventListener('click', () => showSheet(w.week));
272:     weekTabs.appendChild(tab);
273:   }
274:   window.__weeks = weeks;
275: }
276: let curWeek = null;
277: function showSheet(weekNum) {
278:   curWeek = weekNum;
279:   const weeks = window.__weeks;
280:   const w = weeks.find(x => x.week === weekNum);
281:   if (!w) return;
282:   Array.from(weekTabs.children).forEach(c => c.classList.toggle('active', c.textContent === weekLabel(weekNum)));
283:   const net = w.inc - w.exp;
284:   const rows = w.entries.map((e, i) => `
285:     <tr>
286:       <td>${i+1}</td>
287:       <td class="src">${escapeHtml(e.source)}</td>
288:       <td>${escapeHtml(e.description)}</td>
289:       <td class="${e.type}">${e.type.charAt(0).toUpperCase() + e.type.slice(1)}</td>
290:       <td class="amt">${e.type === 'income' ? '+ ' : '− '}${fmtMoney(e.amount)}</td>
291:     </tr>
292:   `).join('');
293:   sheetPreviews.innerHTML = `
294:     <div class="sheet-card" id="sheet-${weekNum}">
295:       <div class="sheet-head">
296:         <div class="sheet-title">Week ${weekNum}</div>
297:         <div class="sheet-meta">
298:           <div><strong>Month:</strong> ${monthName(w.month || currentMonth())} ${currentYear}</div>
299:           <div><strong>Days:</strong> ${(weekNum-1)*7 + 1} – ${Math.min(weekNum*7, 31)}</div>
300:           <div><strong>Entries:</strong> ${w.entries.length}</div>
301:         </div>
302:       </div>
303:       <table class="inv-table">
304:         <thead><tr><th style="width:34px">#</th><th style="width:160px">Source file</th><th>Description</th><th style="width:110px">Type</th><th class="amt" style="width:130px">Amount</th></tr></thead>
305:         <tbody>${rows || '<tr><td colspan="5" style="text-align:center;color:#94a3b8">No entries</td></tr>'}</tbody>
306:         <tfoot>
307:           <tr><td class="label" colspan="4">Total Income</td><td class="amt">+ ${fmtMoney(w.inc)}</td></tr>
308:           <tr><td class="label" colspan="4">Total Expense</td><td class="amt">− ${fmtMoney(w.exp)}</td></tr>
309:           <tr><td class="label" colspan="4">Net</td><td class="amt">${net >= 0 ? '+ ' : '− '}${fmtMoney(Math.abs(net))}</td></tr>
310:         </tfoot>
311:       </table>
312:       <div class="sheet-foot">Sheet: Week ${weekNum} · Gamefy Invoice Builder · ${currentYear}</div>
313:     </div>
314:   `;
315: }
316: function currentMonth() { return files.length ? files[0].month : new Date().getMonth()+1; }
317: 
