  ],
  providers: [MessageService],
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.scss']
})
export class AppComponent implements OnInit, AfterViewInit, OnDestroy {
  // Steps
  step = 1; // 1 = drop, 2 = edit grid, 3 = weekly sheets

  // File state
  pdfFiles: PdfFileInfo[] = [];
  isProcessing = false;
  dragOver = false;

  // UI state
  currentYear = new Date().getFullYear();
  weeks: WeekGroup[] = [];
  activeWeekIndex = 0;

  constructor(private messageService: MessageService) {}

  ngOnInit() {
    // Drop zone is visible by default via CSS class
  }

  ngAfterViewInit() {
    // Ensure pdf.js worker is configured once libs are loaded
    if (typeof pdfjsLib !== 'undefined') {
      pdfjsLib.GlobalWorkerOptions.workerSrc =
        'https://unpkg.com/pdfjs-dist@4.8.69/build/pdf.worker.min.js';
    }
  }

  ngOnDestroy() {}

  /* ------------------------------------------------------------------ */
  /*  Step 1: Drag & drop / file selection                              */
  /* ------------------------------------------------------------------ */

  onDragOver(event: DragEvent) {
    event.preventDefault();
    this.dragOver = true;
  }

  onDragLeave(event: DragEvent) {
    event.preventDefault();
    this.dragOver = false;
  }

  onDrop(event: DragEvent) {
    event.preventDefault();
    this.dragOver = false;
    const files = Array.from(event.dataTransfer?.files || [])
      .filter(f => f.type === 'application/pdf' || f.name.toLowerCase().endsWith('.pdf'));
    this.addFiles(files);
  }

  onFilesSelected(event: any) {
    const files = Array.from(event.target.files || []);
    this.addFiles(files);
  }

  private addFiles(files: File[]) {
    for (const f of files) {
      const parsed = this.parseDayMonth(f.name);
      if (!parsed) {
        this.showToast('warn', `Skipped "${f.name}"`, 'Name must be like 15-03.pdf (day-month)');
        continue;
      }
      const exists = this.pdfFiles.some(
        x => x.name === f.name && x.day === parsed.day && x.month === parsed.month
      );
      if (exists) continue;

      this.pdfFiles.push({
        file: f,
        name: f.name,
        day: parsed.day,
        month: parsed.month,
        year: this.currentYear,
        entries: [],
        processed: false
      });
    }
  }

  removeFile(index: number) {
    this.pdfFiles.splice(index, 1);
  }

  parseDayMonth(name: string): { day: number; month: number } | null {
    const m = name.match(/^(\d{1,2})[-_](\d{1,2})/);
    if (!m) return null;
    return { day: parseInt(m[1], 10), month: parseInt(m[2], 10) };
  }

  /* ------------------------------------------------------------------ */
  /*  PDF processing                                                    */
  /* ------------------------------------------------------------------ */

  async processAll() {
    if (!this.pdfFiles.length) return;
    this.isProcessing = true;

    try {
      for (const f of this.pdfFiles) {
        await this.processPdf(f);
      }
      this.step = 2;
    } catch (err) {
      console.error(err);
      this.showToast('error', 'Processing failed', 'Check the console for details');
    } finally {
      this.isProcessing = false;
    }
  }

  private async processPdf(f: PdfFileInfo) {
    const arrayBuffer = await f.file.arrayBuffer();
    const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;

    const allText: string[] = [];
    for (let i = 1; i <= pdf.numPages; i++) {
      const page = await pdf.getPage(i);
      const content = await page.getTextContent();

      content.items.sort((a: any, b: any) => {
        const ay = a.transform?.[5] || 0;
        const by = b.transform?.[5] || 0;
        if (Math.abs(ay - by) > 2) return by - ay;
        return (a.transform?.[4] || 0) - (b.transform?.[4] || 0);
      });

      allText.push(content.items.map((it: any) => it.str).join(' '));
    }

    f.entries = this.parseTableText(allText.join('\n'), f.day, f.month, f.year);
    f.processed = true;
  }

  private parseTableText(text: string, day: number, month: number, year: number): InvoiceEntry[] {
    const lines = text.split(/\r?\n/).map(l => l.trim()).filter(l => l.length > 0);
    const entries: InvoiceEntry[] = [];

    const moneyRegex = /(-?\d{1,3}(?:[,\.]\d{3})*(?:[.,]\d{2})?|-?\d+(?:[.,]\d{2}))/;
    const incomeK = /income|received|deposit|credit|payment received|salary|revenue/i;
    const expenseK = /expense|paid|purchase|debit|withdrawal|charge|fee|cost/i;

    for (const line of lines) {
      const mm = line.match(moneyRegex);
      if (!mm) continue;

      let cleaned = mm[0].replace(/[^0-9.,-]/g, '');
      const lastDot = cleaned.lastIndexOf('.');
      const lastComma = cleaned.lastIndexOf(',');
      const decSep = lastComma > lastDot ? ',' : '.';

      let intPart: string, decPart: string;
      if (decSep === ',') {
        const p = cleaned.split(',');
        decPart = p.pop()!;
        intPart = p.join('').replace(/\./g, '');
      } else {
        const p = cleaned.split('.');
        decPart = p.pop()!;
        intPart = p.join('').replace(/,/g, '');
      }

      const num = parseFloat((intPart + '.' + decPart).replace(/[^0-9.-]/g, ''));
      if (!isFinite(num)) continue;

      const amount = Math.abs(num);
      let desc = line.replace(moneyRegex, '').trim().replace(/[-–—:|]\s*$/, '').trim();
      if (!desc) desc = 'Entry';

      let type: EntryType = 'expense';
      if (incomeK.test(desc)) type = 'income';
      else if (expenseK.test(desc)) type = 'expense';
      else if (num < 0) type = 'expense';

      entries.push({
        id: crypto.randomUUID?.() ?? `${day}-${month}-${Math.random()}`,
        date: `${String(year).padStart(4, '0')}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`,
        type,
        description: desc,
        amount,
        sourceFile: f.name
      });
    }

    const seen = new Set<string>();
    return entries.filter(e => {
      const k = `${e.date}|${e.type}|${e.description}|${e.amount}`;
      if (seen.has(k)) return false;
      seen.add(k);
      return true;
    });
  }

  /* ------------------------------------------------------------------ */
  /*  Step 2: Live editable grid                                        */
  /* ------------------------------------------------------------------ */

  get allEntries(): InvoiceEntry[] {
    const all: InvoiceEntry[] = [];
    for (const f of this.pdfFiles) {
      all.push(...f.entries);
    }
    return all;
  }

  get totalIncome(): number {
    return this.allEntries.filter(e => e.type === 'income').reduce((s, e) => s + e.amount, 0);
  }

  get totalExpense(): number {
    return this.allEntries.filter(e => e.type === 'expense').reduce((s, e) => s + e.amount, 0);
  }

  get net(): number {
    return this.totalIncome - this.totalExpense;
  }

  addRow() {
    if (!this.pdfFiles.length) {
      this.showToast('warn', 'Add PDFs first', '');
      return;
    }
    const f = this.pdfFiles[this.pdfFiles.length - 1];
    const d = `${this.currentYear}-${String(f.month).padStart(2, '0')}-${String(f.day).padStart(2, '0')}`;
    f.entries.push({
      id: crypto.randomUUID?.() ?? Math.random().toString(),
      date: d,
      type: 'expense',
      description: '',
      amount: 0,
      sourceFile: f.name
    });
  }

  deleteEntry(fileIndex: number, entryIndex: number) {
    this.pdfFiles[fileIndex].entries.splice(entryIndex, 1);
  }

  goToExcel() {
    this.buildWeeks();
    if (!this.weeks.length) {
      this.showToast('warn', 'No data to export', 'Add some entries first');
      return;
    }
    this.step = 3;
  }

  backToData() {
    this.step = 2;
  }

  /* ------------------------------------------------------------------ */
  /*  Step 3: Weekly sheets                                             */
  /* ------------------------------------------------------------------ */

  buildWeeks() {
    const map = new Map<number, WeekGroup>();
    for (const f of this.pdfFiles) {
      for (const e of f.entries) {
        const d = new Date(e.date);
        if (isNaN(d.getTime())) continue;
        const wk = Math.ceil(d.getDate() / 7);
        if (!map.has(wk)) {
          map.set(wk, { week: wk, month: d.getMonth() + 1, entries: [], income: 0, expense: 0 });
        }
        const w = map.get(wk)!;
        w.entries.push({ ...e, sourceFile: f.name });
        if (e.type === 'income') w.income += e.amount;
        else w.expense += e.amount;
      }
    }
    this.weeks = Array.from(map.values()).sort((a, b) => a.week - b.week);
    this.activeWeekIndex = 0;
  }

  weekLabel(w: WeekGroup): string {
    const start = (w.week - 1) * 7 + 1;
    let end = w.week * 7;
    if (end > 31) end = 31;
    return `Week ${w.week} (days ${start}–${end})`;
  }

  monthName(month: number): string {
    return new Date(this.currentYear, month - 1, 1).toLocaleString(undefined, { month: 'long' });
  }

  /* ------------------------------------------------------------------ */
  /*  Excel export (one sheet per week)                                 */
  /* ------------------------------------------------------------------ */

  downloadExcel() {
    if (!this.weeks.length) {
      this.showToast('warn', 'Nothing to export', '');
      return;
    }

    const wb = XLSX.utils.book_new();

    for (const w of this.weeks) {
      const rows: any[][] = [['#', 'Source file', 'Date', 'Description', 'Type', 'Amount']];
      w.entries.forEach((e, i) => {
        rows.push([
          i + 1,
          e.sourceFile,
          e.date,
          e.description,
          e.type.charAt(0).toUpperCase() + e.type.slice(1),
          e.type === 'income' ? +e.amount : -e.amount
        ]);
      });
      rows.push(['', '', '', 'Total Income', '', w.income]);
      rows.push(['', '', '', 'Total Expense', '', -w.expense]);
      rows.push(['', '', '', 'Net', '', w.income - w.expense]);

      const ws = XLSX.utils.aoa_to_sheet(rows);
      ws['!cols'] = [
        { width: 5 }, { width: 22 }, { width: 12 }, { width: 38 }, { width: 12 }, { width: 14 }
      ];
      XLSX.utils.book_append_sheet(wb, ws, `Week ${w.week}`);
    }

    const month = this.pdfFiles.length ? this.pdfFiles[0].month : new Date().getMonth() + 1;
    const fname = `Gamefy_Invoices_Month${String(month).padStart(2, '0')}_${this.currentYear}.xlsx`;
    XLSX.writeFile(wb, fname);
    this.showToast('success', 'Downloaded', fname);
  }

  /* ------------------------------------------------------------------ */
  /*  Helpers                                                           */
  /* ------------------------------------------------------------------ */

  showToast(severity: 'success' | 'info' | 'warn' | 'error', summary: string, detail: string) {
    this.messageService.add({ severity, summary, detail, life: 4000 });
  }

  formatMoney(n: number): string {
    const v = Number(n) || 0;
    return v.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  }

  trackByEntry(index: number, e: InvoiceEntry) {
    return e.id;
  }
}

