declare const pdfjsLib: any;
declare const XLSX: any;

function waitForLib(name: string, check: () => boolean, timeout = 30000): Promise<void> {
  return new Promise((resolve, reject) => {
    const start = Date.now();
    const poll = () => {
      if (check()) {
        resolve();
      } else if (Date.now() - start > timeout) {
        reject(new Error(`${name} library did not load in time`));
      } else {
        setTimeout(poll, 100);
      }
    };
    poll();
  });
}

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [
    CommonModule,
    FormsModule,
    TableModule,
    ButtonModule,
    CardModule,
    InputTextModule,
    DropdownModule,
    InputNumberModule,
    TabViewModule,
    ToastModule,
    FileUploadModule,
    ProgressSpinnerModule,
    CalendarModule
  ],
  providers: [MessageService],
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.scss']
})
export class AppComponent implements OnInit, AfterViewInit, OnDestroy {
  // Steps
  step = 1; // 1 = drop, 2 = edit grid, 3 = weekly sheets

  // File state
  pdfFiles: PdfFileInfo[] = [];
  isProcessing = false;
  dragOver = false;
  libsReady = false;

  // UI state
  currentYear = new Date().getFullYear();
  weeks: WeekGroup[] = [];
  activeWeekIndex = 0;

  constructor(private messageService: MessageService) {}

  async ngOnInit() {
    // Drop zone is visible by default via CSS class
    try {
      await waitForLib('pdfjs', () => typeof pdfjsLib !== 'undefined');
      await waitForLib('xlsx', () => typeof XLSX !== 'undefined');
      this.libsReady = true;

      if (typeof pdfjsLib !== 'undefined') {
        pdfjsLib.GlobalWorkerOptions.workerSrc =
          'https://unpkg.com/pdfjs-dist@4.8.69/build/pdf.worker.min.js';
      }
    } catch (err) {
      console.error(err);
      this.showToast('error', 'Library load failed', 'Please refresh the page and check your internet connection');
    }
  }

  ngAfterViewInit() {}
  ngOnDestroy() {}

  /* ------------------------------------------------------------------ */
  /*  Step 1: Drag & drop / file selection                              */
  /* ------------------------------------------------------------------ */

  onDragOver(event: DragEvent) {
    event.preventDefault();
    this.dragOver = true;
  }

  onDragLeave(event: DragEvent) {
    event.preventDefault();
    this.dragOver = false;
  }

  onDrop(event: DragEvent) {
    event.preventDefault();
    this.dragOver = false;
    const fileList = event.dataTransfer?.files;
    const files = fileList ? Array.from(fileList) as File[] : [];
    const pdfs = files.filter(f => f.type === 'application/pdf' || f.name.toLowerCase().endsWith('.pdf'));
    this.addFiles(pdfs);
  }

  onFilesSelected(event: any) {
    const fileList = event.target.files;
    const files = fileList ? Array.from(fileList) as File[] : [];
    this.addFiles(files);
  }

  private addFiles(files: File[]) {
    for (const f of files) {
      const parsed = this.parseDayMonth(f.name);
      if (!parsed) {
        this.showToast('warn', `Skipped "${f.name}"`, 'Name must be like 15-03.pdf (day-month)');
        continue;
      }
      const exists = this.pdfFiles.some(
        x => x.name === f.name && x.day === parsed.day && x.month === parsed.month
      );
      if (exists) continue;

      this.pdfFiles.push({
        file: f,
        name: f.name,
        day: parsed.day,
        month: parsed.month,
        year: this.currentYear,
        entries: [],
        processed: false
      });
    }
  }

  removeFile(index: number) {
    this.pdfFiles.splice(index, 1);
  }

  parseDayMonth(name: string): { day: number; month: number } | null {
    const m = name.match(/^(\d{1,2})[-_](\d{1,2})/);
    if (!m) return null;
    return { day: parseInt(m[1], 10), month: parseInt(m[2], 10) };
  }

  /* ------------------------------------------------------------------ */
  /*  PDF processing                                                    */
  /* ------------------------------------------------------------------ */

  async processAll() {
    if (!this.pdfFiles.length) return;
    if (!this.libsReady) {
      this.showToast('error', 'Libraries not ready', 'Please wait for pdf.js and SheetJS to load');
      return;
    }
    this.isProcessing = true;

    try {
      for (const f of this.pdfFiles) {
        await this.processPdf(f);
      }
      this.step = 2;
    } catch (err) {
      console.error(err);
      this.showToast('error', 'Processing failed', 'Check the console for details');
    } finally {
