input.content:
/* ============================================
   Gamefy Invoice Builder — Custom Styles
   ============================================ */

:root {
  --app-primary: #2563eb;
  --app-primary-hover: #1d4ed8;
  --app-bg: #f3f4f6;
  --app-card-bg: #ffffff;
  --app-text: #111827;
  --app-text-muted: #6b7280;
  --app-border: #e5e7eb;
  --app-radius: 12px;
  --app-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  --app-shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
}

html, body {
  margin: 0;
  padding: 0;
  background: var(--app-bg);
  color: var(--app-text);
  font-family: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  min-height: 100vh;
}

.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 20px 60px;
}

/* ===== Header ===== */
.app-header {
  text-align: center;
  padding: 48px 20px 24px;
  margin-bottom: 32px;
}

.header-content {
  display: inline-block;
  text-align: left;
}

.brand-icon {
  font-size: 2.5rem;
  margin-right: 12px;
  vertical-align: middle;
}

.brand-title {
  font-size: 2rem;
  font-weight: 800;
  margin: 0 0 8px;
  letter-spacing: -0.5px;
  color: var(--app-text);
  display: inline-block;
}

.brand-subtitle {
  font-size: 1rem;
  color: var(--app-text-muted);
  margin: 0;
  font-weight: 400;
}

/* ===== Step Container ===== */
.app-content {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.step-container {
  width: 100%;
}

.step-card {
  background: var(--app-card-bg);
  border-radius: var(--app-radius);
  box-shadow: var(--app-shadow);
  border: 1px solid var(--app-border);
  overflow: hidden;
  margin-bottom: 24px;
}

.step-header {
  padding: 24px 32px 16px;
  border-bottom: 1px solid var(--app-border);
  display: flex;
  align-items: flex-start;
  gap: 12px;
}

.step-badge {
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 0.875rem;
  flex-shrink: 0;
  margin-top: 2px;
}

.step-title {
  margin: 0 0 4px;
  font-size: 1.375rem;
  font-weight: 700;
  color: var(--app-text);
}

.step-subtitle {
  margin: 0;
  font-size: 0.95rem;
  color: var(--app-text-muted);
}

.step-body {
  padding: 24px 32px 32px;
}

/* ===== Drop Zone ===== */
.drop-zone-card {
  border: 2px dashed var(--app-border) !important;
  background: #fafbfc;
  border-radius: var(--app-radius);
  padding: 48px 32px;
  text-align: center;
  cursor: pointer;
  transition: all 0.2s ease;
  position: relative;
}

.drop-zone-card:hover,
.drop-zone-card.p-card-dragover,
.drop-zone-card.dragover {
  border-color: var(--app-primary) !important;
  background: #eff6ff;
}

.drop-zone-card.p-card-dragover .drop-zone-content,
.drop-zone-card.dragover .drop-zone-content {
  opacity: 0.7;
}

.drop-zone-content {
  transition: opacity 0.2s ease;
}

.drop-zone-icon {
  font-size: 3rem;
  margin-bottom: 16px;
  display: block;
}

.drop-zone-title {
  margin: 0 0 8px;
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--app-text);
}

.drop-zone-hint {
  margin: 0 0 8px;
  color: var(--app-text-muted);
  font-size: 0.95rem;
}

.drop-zone-browse {
  color: var(--app-primary);
  font-weight: 600;
  text-decoration: underline;
  cursor: pointer;
  margin-left: 4px;
}

.drop-zone-browse:hover {
  color: var(--app-primary-hover);
}

.drop-zone-tip {
  margin: 12px 0 0;
  font-size: 0.85rem;
  color: #9ca3af;
}

/* ===== File List ===== */
.file-list-section {
  margin-top: 24px;
}

.file-list-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
}

.file-list-title {
  margin: 0;
  font-size: 1rem;
  font-weight: 600;
  color: var(--app-text);
}

.file-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.file-card-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 18px;
  gap: 16px;
}

.file-card-content {
  display: flex;
  width: 100%;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.file-info {
  display: flex;
  align-items: center;
  gap: 10px;
  flex: 1;
  min-width: 0;
}

.file-name {
  font-weight: 600;
  color: var(--app-text);
  font-size: 0.95rem;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.file-badge {
  font-size: 0.75rem;
  padding: 4px 10px;
  font-weight: 600;
  white-space: nowrap;
}

.file-meta {
  display: flex;
  gap: 16px;
  font-size: 0.85rem;
  color: var(--app-text-muted);
  flex-shrink: 0;
}

.meta-item {
  display: flex;
  align-items: center;
  gap: 6px;
}

.meta-item i {
  font-size: 0.9rem;
  color: #9ca3af;
}

/* ===== Step Summary ===== */
.step-summary {
  display: flex;
  gap: 16px;
  margin-top: 20px;
  padding: 16px 20px;
  background: #f9fafb;
  border-radius: 8px;
  border: 1px solid var(--app-border);
}

.summary-item {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.summary-value {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--app-text);
}

.summary-label {
  font-size: 0.8rem;
  color: var(--app-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

/* ===== Step Actions ===== */
.step-actions {
  margin-top: 24px;
  text-align: center;
}

.p-button-block {
  width: 100%;
  max-width: 400px;
  margin: 0 auto;
}

/* ===== Grid Toolbar ===== */
.grid-toolbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
  flex-wrap: wrap;
  gap: 12px;
}

.grid-toolbar-left {
  display: flex;
  gap: 8px;
}

/* ===== Editable Table ===== */
.p-datatable-edit {
  border: 1px solid var(--app-border) !important;
  border-radius: 8px !important;
  overflow: hidden;
}

.p-datatable-edit .p-datatable-thead > tr > th {
  background: #f9fafb;
  color: var(--app-text-muted);
  font-weight: 600;
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  border-bottom: 2px solid var(--app-border);
  padding: 12px 10px;
}

.p-datatable-edit .p-datatable-tbody > tr {
  border-bottom: 1px solid #f3f4f6;
  transition: background 0.15s;
}

.p-datatable-edit .p-datatable-tbody > tr:hover {
  background: #f9fafb;
}

.p-datatable-edit .p-datatable-tbody > tr.income-row {
  background: #f0fdf4;
}

.p-datatable-edit .p-datatable-edit .p-datatable-tbody > tr.expense-row {
  background: #fef2f2;
}

.p-datatable-edit .p-datatable-tbody > tr td {
  padding: 10px 12px;
  vertical-align: middle;
}

.editable-cell {
  width: 100%;
  padding: 6px 8px;
  font-size: 0.9rem;
}

.source-cell {
  font-size: 0.85rem;
  color: var(--app-text-muted);
  font-weight: 500;
}

.income-row td {
  color: #166534;
}

.expense-row td {
  color: #dc2626;
}

/* ===== Grid Summary ===== */
.grid-summary-card {
  margin-top: 20px;
  border: 1px solid var(--app-border);
}

.grid-summary-content {
  display: flex;
  gap: 24px;
  padding: 20px 24px;
  flex-wrap: wrap;
}

.summary-stat {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 140px;
}

.stat-icon {
  font-size: 1.5rem;
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  background: #f3f4f6;
  color: var(--app-text-muted);
}

.income-stat .stat-icon {
  background: #dcfce7;
  color: #166534;
}

.expense-stat .stat-icon {
  background: #fee2e2;
  color: #dc2626;
}

.net-stat .stat-icon {
  background: #dbeafe;
  color: #2563eb;
}

.rows-stat .stat-icon {
  background: #f3f4f6;
  color: #6b7280;
}

.stat-value {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--app-text);
}

.income .stat-value {
  color: #166534;
}

.expense .stat-value {
  color: #dc2626;
}

.net .stat-value {
  color: #2563eb;
}

.net-positive {
  color: #166534 !important;
}

.net-negative {
  color: #dc2626 !important;
}

.stat-label {
  font-size: 0.8rem;
  color: var(--app-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  font-weight: 600;
}

/* ===== Week Toolbar ===== */
.week-toolbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
  flex-wrap: wrap;
  gap: 12px;
}

/* ===== Weekly Sheets ===== */
.p-tabview .p-tabview-panels {
  padding: 0;
}

.p-tabview .p-tabview-nav {
  border-bottom: 2px solid var(--app-border);
  gap: 0;
}

.p-tabview .p-tabview-nav .p-tabview-tab {
  border: none;
  border-bottom: 3px solid transparent;
  margin-bottom: -2px;
  color: var(--app-text-muted);
  font-weight: 600;
  font-size: 0.9rem;
  padding: 16px 20px;
  transition: all 0.2s;
}

.p-tabview .p-tabview-nav .p-tabview-tab.p-highlight {
  color: var(--app-primary);
  border-bottom-color: var(--app-primary);
}

.p-tabview .p-tabview-nav .p-tabview-tab:hover:not(.p-highlight) {
  color: var(--app-text);
  background: #f9fafb;
}

.week-card {
  margin-top: 20px;
  border: 1px solid var(--app-border);
  overflow: hidden;
}

.week-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px 24px;
  border-bottom: 1px solid var(--app-border);
  background: #f9fafb;
}

.week-title {
  margin: 0 0 4px;
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--app-text);
}

.week-sub {
  margin: 0;
  font-size: 0.85rem;
  color: var(--app-text-muted);
}

.p-datatable-week {
  border: 1px solid var(--app-border) !important;
  border-radius: 0 !important;
}

.p-datatable-week .p-datatable-thead > tr > th {
  background: #f9fafb;
  color: var(--app-text-muted);
  font-weight: 600;
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  border-bottom: 2px solid var(--app-border);
  padding: 10px 12px;
}

.p-datatable-week .p-datatable-tbody > tr td {
  padding: 10px 12px;
  vertical-align: middle;
  border-bottom: 1px solid #f3f4f6;
}

.type-badge {
  font-size: 0.75rem;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 20px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.type-income {
  background: #dcfce7;
  color: #166534;
}

.type-expense {
  background: #fee2e2;
  color: #dc2626;
}

/* ===== Week Totals ===== */
.week-totals {
  margin-top: 16px !important;
}

.totals-grid {
  display: flex;
  gap: 16px;
  justify-content: flex-end;
  flex-wrap: wrap;
}

.total-item {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 140px;
}

.total-label {
  font-size: 0.75rem;
  color: var(--app-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  font-weight: 600;
}

.total-value {
  font-size: 1rem;
  font-weight: 700;
  color: var(--app-text);
}

.income-total .total-value {
  color: #166534;
}

.expense-total .total-value {
  color: #dc2626;
}

.net-total .total-value {
  color: #2563eb;
}

.week-footer {
  margin: 16px 24px 24px;
  font-size: 0.78rem;
  color: #9ca3af;
  text-align: center;
}

/* ===== File Upload Override ===== */
.p-fileupload {
  display: none !important;
}

/* PrimeNG theme tweaks */
.p-button {
  border-radius: 8px;
  font-weight: 600;
  padding: 0.625rem 1rem;
  font-size: 0.9rem;
}

.p-button-sm {
  padding: 0.5rem 0.875rem;
  font-size: 0.85rem;
}

.p-button-lg {
  padding: 0.875rem 1.5rem;
  font-size: 1rem;
}

.p-card {
  border-radius: var(--app-radius);
}

.p-inputtext-sm {
  font-size: 0.875rem;
  padding: 0.5rem 0.75rem;
}

.p-dropdown-sm {
  font-size: 0.875rem;
}

/* ===== Toast ===== */
.p-toast {
  margin-top: 10px;
}

/* ===== Footer ===== */
.app-footer {
  text-align: center;
  padding: 32px 20px;
  color: #9ca3af;
  font-size: 0.85rem;
}

/* ===== Responsive ===== */
@media (max-width: 640px) {
  .app-container {
    padding: 0 12px 40px;
  }

  .app-header {
    padding: 32px 12px 20px;
  }

  .brand-title {
    font-size: 1.5rem;
  }

  .step-header {
    padding: 20px 20px 12px;
    flex-direction: column;
    align-items: flex-start;
    gap: 8px;
  }

  .step-body {
    padding: 20px 20px 24px;
  }

  .drop-zone-card {
    padding: 32px 20px;
  }

  .drop-zone-icon {
    font-size: 2.5rem;
  }

  .file-card-item {
    flex-direction: column;
    align-items: flex-start;
    gap: 12px;
  }

  .file-card-content {
    flex-direction: column;
    align-items: flex-start;
    width: 100%;
  }

  .file-meta {
    width: 100%;
  }

  .file-info {
    width: 100;
  }

  .grid-toolbar {
    flex-direction: column;
    align-items: stretch;
  }

  .grid-toolbar-left {
    flex-direction: column;
    align-items: stretch;
  }

  .grid-toolbar-left button {
    width: 100%;
  }

  .step-actions .p-button-block {
    max-width: 100%;
  }

  .p-tabview .p-tabview-nav .p-tabview-tab {
    padding: 12px 16px;
    font-size: 0.8rem;
