async ngOnInit() {
  // Drop zone is visible by default via CSS class
  try {
    // Dynamically load libraries and wait for them
    await loadScript('https://unpkg.com/pdfjs-dist@4.8.69/build/pdf.min.js');
    await loadScript('https://unpkg.com/pdfjs-dist@4.8.69/build/pdf.worker.min.js');
    await loadScript('https://unpkg.com/xlsx@0.18.5/dist/xlsx.full.min.js');

    this.libsReady = true;

    if (typeof pdfjsLib !== 'undefined') {
      pdfjsLib.GlobalWorkerOptions.workerSrc =
        'https://unpkg.com/pdfjs-dist@4.8.69/build/pdf.worker.min.js';
    }

    // Verify libraries are actually available
    const pdfOk = await waitForLib('pdfjs', () => typeof pdfjsLib !== 'undefined', 5000);
    const xlsxOk = await waitForLib('xlsx', () => typeof XLSX !== 'undefined', 5000);

    if (!pdfOk || !xlsxOk) {
      this.showToast('error', 'Library load failed', 'pdf.js or SheetJS did not load. Refresh the page.');
      this.libsReady = false;
    }
  } catch (err) {
    console.error(err);
    this.showToast('error', 'Library load failed', 'Please refresh the page and check your internet connection');
    this.libsReady = false;
  }
}

