import * as XLSX from 'xlsx';
import { InvoiceEntry, PdfFileInfo, WeekGroup, EntryType } from './models/invoice-entry.model';

declare const pdfjsLib: any;

function waitForPdfJs(timeout = 15000): Promise<boolean> {
  return new Promise((resolve) => {
    const start = Date.now();
    const poll = () => {
      if (typeof pdfjsLib !== 'undefined') {
        resolve(true);
      } else if (Date.now() - start > timeout) {
        resolve(false);
      } else {
        setTimeout(poll, 100);
      }
    };
    poll();
  });
}

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [
    CommonModule,
    FormsModule,
    TableModule,
    ButtonModule,
    CardModule,
    InputTextModule,
    DropdownModule,
    InputNumberModule,
    TabViewModule,
    ToastModule,
