import { Component, OnInit, AfterViewInit, OnDestroy, HostListener } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { MessageService } from 'primeng/api';
import { ButtonModule } from 'primeng/button';
import { CardModule } from 'primeng/card';
import { InputTextModule } from 'primeng/inputtext';
import { DropdownModule } from 'primeng/dropdown';
import { InputNumberModule } from 'primeng/inputnumber';
import { TabViewModule } from 'primeng/tabview';
import { ToastModule } from 'primeng/toast';
import { ProgressSpinnerModule } from 'primeng/progressspinner';
import { ChipModule } from 'primeng/chip';
import * as XLSX from 'xlsx';
import { InvoiceEntry, PdfFileInfo, EntryType } from './models/invoice-entry.model';

declare const pdfjsLib: any;

function waitForPdfJs(timeout = 15000): Promise<boolean> {
  return new Promise((resolve) => {
    const start = Date.now();
    const poll = () => {
      if (typeof pdfjsLib !== 'undefined') {
        resolve(true);
      } else if (Date.now() - start > timeout) {
        resolve(false);
      } else {
        setTimeout(poll, 100);
      }
    };
    poll();
  });
}

const EXCEL_COLS = [
  { key: 'rowNum', label: '#', width: 50, editable: false },
  { key: 'date', label: 'Date', width: 110, editable: true },
  { key: 'type', label: 'Type', width: 100, editable: true },
  { key: 'description', label: 'Description', width: 260, editable: true },
  { key: 'amount', label: 'Amount', width: 120, editable: true, align: 'right' },
  { key: 'sourceFile', label: 'Source File', width: 150, editable: false },
];

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [
    CommonModule,
    FormsModule,
    ButtonModule,
    CardModule,
    InputTextModule,
    DropdownModule,
    InputNumberModule,
    TabViewModule,
    ToastModule,
    ProgressSpinnerModule,
    ChipModule
  ],
  providers: [MessageService],
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.scss']
})
export class AppComponent implements OnInit, AfterViewInit, OnDestroy {
  // Steps
  step = 1; // 1 = drop, 2 = file tabs

  // File state
  pdfFiles: PdfFileInfo[] = [];
  isProcessing = false;
  dragOver = false;
  libsReady = false;
  loadingLibs = false;

  // UI state
  currentYear = new Date().getFullYear();
  activeTabIndex = 0;

  // Excel grid state (per active tab)
  activeRow: number | null = null;
  activeCol: number | null = null;
  editValue = '';

  entryTypeOptions = [
    { label: 'Income', value: 'income' },
    { label: 'Expense', value: 'expense' }
  ];

  Math = Math;
  EXCEL_COLS = EXCEL_COLS;

  constructor(private messageService: MessageService) {}

  async ngOnInit() {
    this.loadingLibs = true;
    try {
      const ready = await waitForPdfJs();
      if (ready) {
        this.libsReady = true;
        pdfjsLib.GlobalWorkerOptions.workerSrc = 'assets/pdfjs/pdf.worker.js';
      } else {
        this.showToast('error', 'Library load failed', 'pdf.js did not load. Refresh the page.');
      }
    } catch (err) {
      console.error(err);
      this.showToast('error', 'Library load failed', 'Refresh the page and try again.');
    } finally {
      this.loadingLibs = false;
    }
  }

  ngAfterViewInit() {}
  ngOnDestroy() {}

  /* ------------------------------------------------------------------ */
  /*  Step 1: Drag & drop / file selection                              */
  /* ------------------------------------------------------------------ */

  onDragOver(event: DragEvent) {
    event.preventDefault();
    this.dragOver = true;
  }

  onDragLeave(event: DragEvent) {
    event.preventDefault();
    this.dragOver = false;
  }

  onDrop(event: DragEvent) {
    event.preventDefault();
    this.dragOver = false;
    const fileList = event.dataTransfer?.files;
    const files = fileList ? Array.from(fileList) as File[] : [];
    const pdfs = files.filter(f => f.type === 'application/pdf' || f.name.toLowerCase().endsWith('.pdf'));
    this.addFiles(pdfs);
  }

  onFilesSelected(event: any) {
    const fileList = event.target.files;
    const files = fileList ? Array.from(fileList) as File[] : [];
    this.addFiles(files);
  }

  private addFiles(files: File[]) {
    for (const f of files) {
      const parsed = this.parseDayMonth(f.name);
      if (!parsed) {
        this.showToast('warn', `Skipped "${f.name}"`, 'Name must be like 15-03.pdf (day-month)');
        continue;
      }
      const exists = this.pdfFiles.some(
        x => x.name === f.name && x.day === parsed.day && x.month === parsed.month
      );
      if (exists) continue;

      this.pdfFiles.push({
        file: f,
        name: f.name,
        day: parsed.day,
        month: parsed.month,
        year: this.currentYear,
        entries: [],
        processed: false,
        cashAmount: 0,
        tpeAmount: 0
      });
    }
    if (this.pdfFiles.length) {
      this.step = 2;
      this.resetExcelSelection();
    }
  }

  removeFile(index: number) {
    this.pdfFiles.splice(index, 1);
    if (this.pdfFiles.length === 0) {
      this.step = 1;
      this.activeTabIndex = 0;
    } else if (this.activeTabIndex >= this.pdfFiles.length) {
      this.activeTabIndex = this.pdfFiles.length - 1;
    }
    this.resetExcelSelection();
  }

  parseDayMonth(name: string): { day: number; month: number } | null {
    const m = name.match(/^(\d{1,2})[-_](\d{1,2})/);
    if (!m) return null;
    return { day: parseInt(m[1], 10), month: parseInt(m[2], 10) };
  }

  /* ------------------------------------------------------------------ */
  /*  PDF processing                                                    */
  /* ------------------------------------------------------------------ */

  async processAll() {
    if (!this.pdfFiles.length) return;
    if (!this.libsReady) {
      this.showToast('error', 'Libraries not ready', 'Please wait for pdf.js to load');
      return;
    }
    this.isProcessing = true;

    try {
      for (const f of this.pdfFiles) {
        await this.processPdf(f);
      }
    } catch (err) {
      console.error(err);
      this.showToast('error', 'Processing failed', 'Check the console for details');
    } finally {
      this.isProcessing = false;
    }
  }

  processSingle(f: PdfFileInfo) {
    if (!this.libsReady) {
      this.showToast('error', 'Libraries not ready', 'Please wait for pdf.js to load');
      return;
    }
    this.processPdf(f);
  }

  private async processPdf(f: PdfFileInfo) {
    const arrayBuffer = await f.file.arrayBuffer();
    const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;

    const allText: string[] = [];
    for (let i = 1; i <= pdf.numPages; i++) {
      const page = await pdf.getPage(i);
      const content = await page.getTextContent();

      content.items.sort((a: any, b: any) => {
        const ay = a.transform?.[5] || 0;
        const by = b.transform?.[5] || 0;
        if (Math.abs(ay - by) > 2) return by - ay;
        return (a.transform?.[4] || 0) - (b.transform?.[4] || 0);
      });

      allText.push(content.items.map((it: any) => it.str).join(' '));
    }

    f.entries = this.parseTableText(allText.join('\n'), f.day, f.month, f.year, f.name);
    f.processed = true;
  }

  private parseTableText(text: string, day: number, month: number, year: number, sourceFile: string): InvoiceEntry[] {
    const lines = text.split(/\r?\n/).map(l => l.trim()).filter(l => l.length > 0);
    const entries: InvoiceEntry[] = [];

    const moneyRegex = /(-?\d{1,3}(?:[,\.]\d{3})*(?:[.,]\d{2})?|-?\d+(?:[.,]\d{2}))/;
    const incomeK = /income|received|deposit|credit|payment received|salary|revenue/i;
    const expenseK = /expense|paid|purchase|debit|withdrawal|charge|fee|cost/i;

    for (const line of lines) {
      const mm = line.match(moneyRegex);
      if (!mm) continue;

      let cleaned = mm[0].replace(/[^0-9.,-]/g, '');
      const lastDot = cleaned.lastIndexOf('.');
      const lastComma = cleaned.lastIndexOf(',');
      const decSep = lastComma > lastDot ? ',' : '.';

      let intPart: string, decPart: string;
      if (decSep === ',') {
        const p = cleaned.split(',');
        decPart = p.pop()!;
        intPart = p.join('').replace(/\./g, '');
      } else {
        const p = cleaned.split('.');
        decPart = p.pop()!;
        intPart = p.join('').replace(/,/g, '');
      }

      const num = parseFloat((intPart + '.' + decPart).replace(/[^0-9.-]/g, ''));
      if (!isFinite(num)) continue;

      const amount = Math.abs(num);
      let desc = line.replace(moneyRegex, '').trim().replace(/[-–—:|]\s*$/, '').trim();
      if (!desc) desc = 'Entry';

      let type: EntryType = 'expense';
      if (incomeK.test(desc)) type = 'income';
      else if (expenseK.test(desc)) type = 'expense';
      else if (num < 0) type = 'expense';

      entries.push({
        id: crypto.randomUUID?.() ?? `${day}-${month}-${Math.random()}`,
        date: `${String(year).padStart(4, '0')}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`,
        type,
        description: desc,
        amount,
        sourceFile
      });
    }

    const seen = new Set<string>();
    return entries.filter(e => {
      const k = `${e.date}|${e.type}|${e.description}|${e.amount}`;
      if (seen.has(k)) return false;
      seen.add(k);
      return true;
    });
  }

  /* ------------------------------------------------------------------ */
  /*  Excel grid                                                        */
  /* ------------------------------------------------------------------ */

  get currentFile(): PdfFileInfo | undefined {
    return this.pdfFiles[this.activeTabIndex];
  }

  resetExcelSelection() {
    this.activeRow = null;
    this.activeCol = null;
    this.editValue = '';
  }

  selectCell(row: number, col: number) {
    this.activeRow = row;
    this.activeCol = col;
    this.editValue = this.getCellValue(row, col);
  }

  getCellValue(row: number, col: number): string {
    const f = this.currentFile;
    if (!f) return '';
    const e = f.entries[row];
    if (!e) return '';
    const key = EXCEL_COLS[col].key;
    switch (key) {
      case 'rowNum': return String(row + 1);
      case 'date': return e.date;
      case 'type': return e.type.charAt(0).toUpperCase() + e.type.slice(1);
      case 'description': return e.description;
      case 'amount': return String(e.amount);
      case 'sourceFile': return e.sourceFile;
      default: return '';
    }
  }

  setCellValue(row: number, col: number, value: string) {
    const f = this.currentFile;
    if (!f) return;
    const e = f.entries[row];
    if (!e) return;
    const key = EXCEL_COLS[col].key;
    switch (key) {
      case 'date': e.date = value; break;
      case 'type': e.type = (value.toLowerCase() === 'income' ? 'income' : 'expense') as EntryType; break;
      case 'description': e.description = value; break;
      case 'amount': e.amount = parseFloat(value) || 0; break;
    }
  }

  commitCell() {
    if (this.activeRow != null && this.activeCol != null) {
      this.setCellValue(this.activeRow, this.activeCol, this.editValue);
    }
  }

  startEdit() {
    if (this.activeRow != null && this.activeCol != null) {
      const col = EXCEL_COLS[this.activeCol];
      if (col.editable) {
        this.editValue = this.getCellValue(this.activeRow, this.activeCol);
      }
    }
  }

  moveCell(dr: number, dc: number) {
    const f = this.currentFile;
    if (!f) return;
    let nr = (this.activeRow ?? 0) + dr;
    let nc = (this.activeCol ?? 0) + dc;
    if (nr < 0) nr = 0;
    if (nr >= f.entries.length) nr = f.entries.length - 1;
    if (nr < 0) nr = 0;
    if (nc < 0) nc = 0;
    if (nc >= EXCEL_COLS.length) nc = EXCEL_COLS.length - 1;
    this.commitCell();
    this.selectCell(nr, nc);
  }

  @HostListener('window:keydown', ['$event'])
  onKeyDown(event: KeyboardEvent) {
    // Only handle navigation when a cell is selected and not typing in formula bar
    if (this.activeRow == null || this.activeCol == null) return;
    const target = event.target as HTMLElement;
    if (target.tagName === 'INPUT' && target.classList.contains('formula-input')) return;

    if (event.key === 'ArrowDown') { event.preventDefault(); this.moveCell(1, 0); }
    else if (event.key === 'ArrowUp') { event.preventDefault(); this.moveCell(-1, 0); }
    else if (event.key === 'ArrowRight') { event.preventDefault(); this.moveCell(0, 1); }
    else if (event.key === 'ArrowLeft') { event.preventDefault(); this.moveCell(0, -1); }
    else if (event.key === 'Enter') { event.preventDefault(); this.commitCell(); this.moveCell(1, 0); }
    else if (event.key === 'Tab') { event.preventDefault(); this.commitCell(); this.moveCell(0, 1); }
    else if (event.key === 'Delete' || event.key === 'Backspace') {
      event.preventDefault();
      if (this.activeRow != null && this.activeCol != null) {
        const f = this.currentFile;
        if (f) {
          const e = f.entries[this.activeRow];
          if (e) {
            const key = EXCEL_COLS[this.activeCol].key;
            if (key === 'description') e.description = '';
            else if (key === 'amount') e.amount = 0;
            else if (key === 'date') e.date = '';
          }
        }
      }
    } else if ((event.key >= '0' && event.key <= '9') || event.key === '.' || event.key === '-') {
      // Start typing into active editable cell
      const col = EXCEL_COLS[this.activeCol];
      if (col.editable) {
        this.startEdit();
      }
    }
  }

  addRow(f: PdfFileInfo) {
    const d = `${f.year}-${String(f.month).padStart(2, '0')}-${String(f.day).padStart(2, '0')}`;
    f.entries.push({
      id: crypto.randomUUID?.() ?? Math.random().toString(),
      date: d,
      type: 'expense',
      description: '',
      amount: 0,
      sourceFile: f.name
    });
    this.selectCell(f.entries.length - 1, 1); // move to date col of new row
  }

  deleteRow(f: PdfFileInfo, rowIndex: number) {
    f.entries.splice(rowIndex, 1);
    if (this.activeRow != null && this.activeRow >= f.entries.length) {
      this.activeRow = f.entries.length - 1;
    }
    if (this.activeRow != null && this.activeRow < 0) this.activeRow = null;
  }

  /* ------------------------------------------------------------------ */
  /*  Reconciliation                                                    */
  /* ------------------------------------------------------------------ */

  totalAmounts(f: PdfFileInfo): number {
    return f.entries.reduce((s, e) => s + e.amount, 0);
  }

  totalIncome(f: PdfFileInfo): number {
    return f.entries.filter(e => e.type === 'income').reduce((s, e) => s + e.amount, 0);
  }

  totalExpense(f: PdfFileInfo): number {
    return f.entries.filter(e => e.type === 'expense').reduce((s, e) => s + e.amount, 0);
  }

  difference(f: PdfFileInfo): number {
    const total = this.totalAmounts(f);
    const cash = f.cashAmount || 0;
    const tpe = f.tpeAmount || 0;
    return total - (cash + tpe);
  }

  /* ------------------------------------------------------------------ */
  /*  Excel export (one sheet per file/tab)                             */
  /* ------------------------------------------------------------------ */

  downloadExcel() {
    if (!this.pdfFiles.length) {
      this.showToast('warn', 'Nothing to export', '');
      return;
    }

    const wb = XLSX.utils.book_new();

    for (const f of this.pdfFiles) {
      const rows: any[][] = [['#', 'Date', 'Type', 'Description', 'Amount']];
      f.entries.forEach((e, i) => {
        rows.push([
          i + 1,
          e.date,
          e.type.charAt(0).toUpperCase() + e.type.slice(1),
          e.description,
          e.type === 'income' ? +e.amount : -e.amount
        ]);
      });
      rows.push(['', '', '', 'Total Amounts', this.totalAmounts(f)]);
      rows.push(['', '', '', 'Total Cash', f.cashAmount || 0]);
      rows.push(['', '', '', 'Total TPE', f.tpeAmount || 0]);
      rows.push(['', '', '', 'Difference', this.difference(f)]);

      const ws = XLSX.utils.aoa_to_sheet(rows);
      ws['!cols'] = [
        { width: 5 }, { width: 12 }, { width: 10 }, { width: 38 }, { width: 14 }
      ];
      XLSX.utils.book_append_sheet(wb, ws, `Day ${f.day}-${f.month}`);
    }

    const fname = `Gamefy_Daily_Invoices_Month${this.currentYear}.xlsx`;
    XLSX.writeFile(wb, fname);
    this.showToast('success', 'Downloaded', fname);
  }

  /* ------------------------------------------------------------------ */
  /*  Helpers                                                           */
  /* ------------------------------------------------------------------ */

  showToast(severity: 'success' | 'info' | 'warn' | 'error', summary: string, detail: string) {
    this.messageService.add({ severity, summary, detail, life: 4000 });
  }

  formatMoney(n: number): string {
    const v = Number(n) || 0;
    return v.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  }

  trackByEntry(index: number, e: InvoiceEntry) {
    return e.id;
  }

  colLetter(index: number): string {
    const letters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
    if (index < letters.length) return letters[index];
    return letters[Math.floor(index / letters.length) - 1] + letters[index % letters.length];
  }
}

