/* 
  Gamefy Invoice Builder — Plain HTML/JS
  Styled like Tuneps dashboard
*/

:root {
  --bg-primary: #f8fafc;
  --bg-secondary: #ffffff;
  --glass-bg: rgba(255, 255, 255, 0.7);
  --glass-border: rgba(226, 232, 240, 0.6);
  --glass-border-glow: rgba(59, 130, 246, 0.25);

  --accent-cyan: #06b6d4;
  --accent-cyan-glow: rgba(6, 182, 214, 0.2);
  --accent-purple: #8b5cf6;
  --accent-purple-glow: rgba(139, 92, 246, 0.2);
  --accent-emerald: #10b981;
  --accent-emerald-glow: rgba(16, 185, 129, 0.2);
  --accent-amber: #f59e0b;
  --accent-amber-glow: rgba(245, 158, 11, 0.2);
  --accent-rose: #ef4444;
  --accent-rose-glow: rgba(239, 68, 68, 0.2);

  --text-main: #111827;
  --text-muted: #6b7280;
  --text-dark: #374151;

  --shadow-main: 0 10px 30px -5px rgba(0, 0, 0, 0.08);
  --shadow-glow: 0 0 20px 0 rgba(59, 130, 246, 0.15);
  --radius-lg: 16px;
  --radius-md: 10px;
  --radius-sm: 6px;

  --transition-fast: 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  background-color: var(--bg-primary);
  color: var(--text-main);
  font-family: 'Inter', system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
  min-height: 100vh;
  overflow-x: hidden;
  line-height: 1.5;
}

body::before, body::after {
  content: '';
  position: fixed;
  width: 60vw;
