input.newString:
function parseTableText(text, day, month, year, sourceFile) {
  const lines = text.split(/\r?\n/).map(l => l.trim()).filter(l => l.length > 0);
  const entries = [];

  // Amount patterns: "7,00 TND", "17,10 TND", "315,25 TND", etc.
  const amountWithTND = /(-?\d{1,3}(?:[.\s]\d{3})*(?:[,\.]\d{2})?)\s*TND/i;
  // Plain amount: "7,00", "17.10"
  const amountPlain = /(-?\d{1,3}(?:[,\.]\d{3})*(?:[.,]\d{2})?|-?\d+(?:[.,]\d{2}))/;
  // Date: DD.MM.YYYY
  const dateRegex = /(\d{1,2})\.(\d{1,2})\.(\d{4})/;
  // Time: HH:MM:SS
  const timeRegex = /(\d{1,2}:\d{2}:\d{2})/;
  // Type
  const incomeK = /\bincome\b/i;
  const expenseK = /\bexpense\b/i;

  for (const line of lines) {
    // Skip header/footer lines
    if (/page \d+\/\d+/i.test(line)) continue;
    if (/filter status/i.test(line)) continue;
    if (/report result/i.test(line)) continue;
    if (/total amount/i.test(line)) continue;
    if (/cash transactions/i.test(line)) continue;
    if (/credit card/i.test(line)) continue;
    if (/member transactions/i.test(line)) continue;
    if (/stock transactions/i.test(line)) continue;
    if (/cashier|all|date range|payment method|transaction type|income\/expense/i.test(line) && !amountWithTND.test(line)) continue;

    // Try to extract amount with TND first
    let amtMatch = line.match(amountWithTND);
    let amountStr = null;
    let amountPos = -1;
    if (amtMatch) {
      amountStr = amtMatch[1];
      amountPos = amtMatch.index;
    } else {
      const pm = line.match(amountPlain);
      if (pm) {
        amountStr = pm[1];
        amountPos = pm.index;
      }
    }
    if (!amountStr) continue;

    // Parse amount
    let cleaned = amountStr.replace(/[^0-9.,-]/g, '');
    const lastDot = cleaned.lastIndexOf('.');
    const lastComma = cleaned.lastIndexOf(',');
    const decSep = lastComma > lastDot ? ',' : '.';

    let intPart, decPart;
    if (decSep === ',') {
      const p = cleaned.split(',');
      decPart = p.pop();
      intPart = p.join('').replace(/\./g, '');
    } else {
      const p = cleaned.split('.');
      decPart = p.pop();
      intPart = p.join('').replace(/,/g, '');
    }

    const num = parseFloat((intPart + '.' + decPart).replace(/[^0-9.-]/g, ''));
    if (!isFinite(num)) continue;

    const amount = Math.abs(num);

    // Extract type from line
    let type = 'expense';
    if (incomeK.test(line)) type = 'income';
    else if (expenseK.test(line)) type = 'expense';

    // Extract description: everything before the amount, cleaned up
    let beforeAmt = line.substring(0, amountPos).trim();
    let afterAmt = line.substring(amountPos + amountStr.length).trim();
    // Remove "TND" and currency noise from after
    afterAmt = afterAmt.replace(/TND/i, '').trim();

    // Build description: take meaningful parts from before + after
    // Remove common noise words from before
    beforeAmt = beforeAmt.replace(/(cashier|cash|credit card|member|stock)/gi, '').trim();
    // Remove date/time from before
    beforeAmt = beforeAmt.replace(dateRegex, '').trim();
    beforeAmt = beforeAmt.replace(timeRegex, '').trim();
    beforeAmt = beforeAmt.replace(/[-–—:|]\s*$/, '').trim();

    // Remove type keywords from before
    beforeAmt = beforeAmt.replace(/\b(income|expense)\b/gi, '').trim();

    let description = beforeAmt ? beforeAmt + ' — ' + afterAmt : afterAmt;
    description = description.replace(/\s+/g, ' ').trim();
    description = description.replace(/^[-–—:|]\s*/, '').replace(/[-–—:|]\s*$/, '').trim();
    if (!description) description = 'Entry';

    // Use PDF line date if present, otherwise use filename day
    let entryDate = `${String(year).padStart(4, '0')}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
    const dm = line.match(dateRegex);
    if (dm) {
      const d = parseInt(dm[1], 10);
      const m = parseInt(dm[2], 10);
      const y = parseInt(dm[3], 10);
      if (d > 0 && d <= 31 && m > 0 && m <= 12) {
        entryDate = `${String(y).padStart(4, '0')}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
      }
    }

    entries.push({
      id: crypto.randomUUID?.() ?? `${day}-${month}-${Math.random()}`,
      date: entryDate,
      type, description, amount, sourceFile,
    });
  }

  const seen = new Set();
  return entries.filter(e => {
    const k = `${e.date}|${e.type}|${e.description}|${e.amount}`;
    if (seen.has(k)) return false;
    seen.add(k);
    return true;
  });
}

