.reconciliation-card { border: 2px solid var(--accent-cyan); background: #f8fafc; }
.recon-title {
  margin: 0 0 16px; font-size: 1.1rem; font-weight: 700; color: var(--text-main);
  display: flex; align-items: center; gap: 8px;
}
.recon-title::before { content: '💰'; font-size: 1.2rem; }
