// Categorize entries (only income amounts go to categories)
const catTotals = {};
for (const cat of CATEGORIES) catTotals[cat.label] = 0;
catTotals['Other'] = 0;

let totalIncome = 0;
let totalExpense = 0;

for (const e of entries) {
  if (e.type === 'income') totalIncome += e.amount;
  else totalExpense += e.amount;

  // Only categorize income entries
  if (e.type === 'income') {
    const cat = categorize(e.description);
    if (catTotals[cat] !== undefined) {
      catTotals[cat] += e.amount;
    } else {
      catTotals['Other'] += e.amount;
    }
  }
}

// Weekly net total = income - expense
const totalHT = totalIncome - totalExpense;

// Compute weekly Cash/TPE from all source files that have entries in this week
const weekSourceFiles = new Set(entries.map(e => e.sourceFile));
let weekCash = 0;
let weekTpe = 0;
for (const f of pdfFiles) {
  if (weekSourceFiles.has(f.name)) {
    weekCash += f.cashAmount || 0;
    weekTpe += f.tpeAmount || 0;
  }
}

// Build sheet rows
const rows = [];

// Title section
rows.push([weekTitle, '', '', '', '', '']);
rows.push(['Days ' + startDay + ' to ' + endDay, '', '', '', '', '']);
rows.push(['', '', '', '', '', '']);

// Main data table header
rows.push(['#', 'Date', 'Type', 'Description', 'Amount', 'Source File']);

// All entries for this week (merged from all days)
let rowNum = 1;
for (const e of entries) {
  rows.push([
    rowNum++,
    e.date,
    e.type.charAt(0).toUpperCase() + e.type.slice(1),
    e.description,
    e.type === 'income' ? +e.amount : -e.amount,
    e.sourceFile,
  ]);
}

// Weekly totals row
const weekNetTotal = totalIncome - totalExpense;
rows.push(['', '', 'Week Total (Net)', '', weekNetTotal, '']);
rows.push(['', '', '', '', '', '']);

// Accounting summary section (centered below data)
rows.push(['Désignation', 'Montant', '', '', '', '']);
rows.push([weekTitle, '', '', '', '', '']);
rows.push(['', '', '', '', '', '']);

// Category rows (income only)
for (const cat of CATEGORIES) {
  const val = catTotals[cat.label];
  rows.push([cat.label, val === 0 ? '—' : val, '', '', '', '']);
}
rows.push(['Other', catTotals['Other'] === 0 ? '—' : catTotals['Other'], '', '', '', '']);

// Reconciliation rows
rows.push(['Total Amounts', weekNetTotal, '', '', '', '']);
rows.push(['Total Cash', weekCash, '', '', '', '']);
rows.push(['Total TPE', weekTpe, '', '', '', '']);
rows.push(['Difference', weekNetTotal - weekCash - weekTpe, '', '', '', '']);

// Totals
rows.push(['TOTAL HT', totalHT, '', '', '', '']);

