function parseTableText(text, day, month, year, sourceFile) {
  const entries = [];
  const lines = text.split(/\r?\n/).map(l => l.trim()).filter(l => l.length > 0);

  // Skip header/footer lines
  const skipPatterns = [
    /^page \d+\/\d+/i,
    /filter status/i,
    /report result/i,
    /total amount/i,
    /cash transactions/i,
    /credit card/i,
    /member transactions/i,
    /stock transactions/i,
  ];

  for (const line of lines) {
    // Only skip lines that are purely headers (no money amount)
    if (skipPatterns.some(r => r.test(line)) && !/\d{1,3}(?:[.,]\d{2})/.test(line)) continue;
    if (line.length < 5) continue;

    // Find amount in the line: "7,00" or "7,00 TND" or "-5,00"
    const amtRegex = /(-?\d{1,3}(?:[.,]\d{3})*(?:[.,]\d{2})?)(?:\s*TND)?/i;
    const amtMatch = line.match(amtRegex);
    if (!amtMatch) continue;

    const amountStr = amtMatch[1];
    const amountPos = amtMatch.index;

    // Parse amount
    let cleaned = amountStr.replace(/[^0-9.,-]/g, '');
    const lastDot = cleaned.lastIndexOf('.');
    const lastComma = cleaned.lastIndexOf(',');
    const decSep = lastComma > lastDot ? ',' : '.';

    let intPart, decPart;
    if (decSep === ',') {
      const p = cleaned.split(',');
      decPart = p.pop();
      intPart = p.join('').replace(/\./g, '');
    } else {
      const p = cleaned.split('.');
      decPart = p.pop();
      intPart = p.join('').replace(/,/g, '');
    }

    const num = parseFloat((intPart + '.' + decPart).replace(/[^0-9.-]/g, ''));
    if (!isFinite(num)) continue;

    const amount = Math.abs(num) > 0 ? Math.abs(num) : 0;

    // Extract date from line: DD.MM.YYYY
    const dateRegex = /(\d{1,2})\.(\d{1,2})\.(\d{4})/;
    const dm = line.match(dateRegex);
    let entryDate = `${String(year).padStart(4, '0')}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
    if (dm) {
      const dd = parseInt(dm[1], 10);
      const mm = parseInt(dm[2], 10);
      const yy = parseInt(dm[3], 10);
      if (dd > 0 && dd <= 31 && mm > 0 && mm <= 12) {
        entryDate = `${String(yy).padStart(4, '0')}-${String(mm).padStart(2, '0')}-${String(dd).padStart(2, '0')}`;
      }
    }

    // Extract type from line keywords
    let type = 'expense';
    if (/income|received|deposit|credit|salary|revenue/i.test(line)) type = 'income';
    else if (/expense|paid|purchase|debit|withdrawal|charge|fee|cost/i.test(line)) type = 'expense';

    // Description: everything between "Cash/Credit Card/Debit Card" and the amount
    let beforeAmt = line.substring(0, amountPos).trim();
    let afterAmt = line.substring(amountPos + amountStr.length).trim();
    afterAmt = afterAmt.replace(/TND/i, '').trim();

    // Remove date, time, type, payment method from beforeAmt
    beforeAmt = beforeAmt.replace(/\d{1,2}\.\d{1,2}\.\d{4}/g, ' ').trim(); // date
    beforeAmt = beforeAmt.replace(/\d{1,2}:\d{2}:\d{2}/g, ' ').trim();   // time
    beforeAmt = beforeAmt.replace(/\b(Income|Expense)\b/gi, ' ').trim(); // type
    beforeAmt = beforeAmt.replace(/\b(Cash|Credit Card|Debit Card)\b/gi, ' ').trim(); // payment
    beforeAmt = beforeAmt.replace(/\s+/g, ' ').trim();

    description = beforeAmt ? beforeAmt : '';

    // Comment: everything after amount (and optional TND)
    let comment = afterAmt.replace(/\s+/g, ' ').trim();

    if (!description || description.length < 2) description = 'Entry';

    entries.push({
      id: crypto.randomUUID?.() ?? `${day}-${month}-${Math.random()}`,
      date: entryDate,
      type, description, comment, amount,
    });
  }

  const seen = new Set();
  return entries.filter(e => {
    const k = `${e.date}|${e.type}|${e.description}|${e.amount}`;
    if (seen.has(k)) return false;
    seen.add(k);
    return true;
  });
}

